/* ===================================================================
   Elite Digital Hub (Redg.) — CRM
   All data persists in a MongoDB database via a small Express API
   (see /backend). The app still works with plain in-memory arrays
   (items, orders, expenses, ...) exactly like before — only the
   loadJSON()/saveJSON() storage layer changed, from localStorage to
   fetch() calls against the API.
   =================================================================== */

// Base URL of the backend API. Change this if your backend runs
// somewhere else (a different port, or a deployed URL).
// Same-origin by default: works automatically wherever this is deployed,
// since server.js now serves this frontend itself. Only set
// window.EDH_API_BASE (in a small <script> before this file) if the API
// genuinely lives on a different domain/port than this page.
const API_BASE = (window.EDH_API_BASE || '') + '/api';

const STORAGE_KEYS = {
  ITEMS: 'items',
  ORDERS: 'orders',
  EXPENSES: 'expenses',
  HISTORY: 'history',
  INVOICES: 'invoices',
  USERS: 'users',
  TASKS: 'tasks',
  STOCK_LEDGER: 'stockmoves',
  PASSWORD_REQUESTS: 'passwordrequests',
  PHOTO_REQUESTS: 'photorequests',
};

// Default values for every configurable list in the app (categories,
// statuses, priorities, roles). These are only used the very first time
// the app runs against an empty database — after that, whatever the
// Owner edits in Settings → Manage Lists is what's used everywhere.
//
// Roles: "fullAccess" = this role always has full module access, no need
// to tick individual permission checkboxes on a user. "isOwner" = this
// role additionally gets Owner-only powers (Users tab, Import Backup,
// Erase All Data, Manage Lists) and is protected — the app will not let
// the last remaining Owner-flagged user be deleted, demoted, or deactivated.
