/* ---------------------------------------------------------------
   Storage helpers (now backed by the database via the API, not
   localStorage). Kept the same names/signatures on purpose so the
   rest of the app (which calls loadJSON/saveJSON everywhere) did
   not need to change.
   --------------------------------------------------------------- */

// Loads one full collection from the database. Used only at startup.
async function loadJSON(key, fallback){
  try{
    const res = await fetch(`${API_BASE}/${key}`);
    if (!res.ok) throw new Error('Bad response: ' + res.status);
    const data = await res.json();
    return Array.isArray(data) && data.length ? data : fallback;
  }catch(e){
    console.error(`Failed to load "${key}" from database:`, e);
    return fallback;
  }
}

// Saves (replaces) one full collection in the database. This mirrors
// the old localStorage.setItem(key, wholeArray) behaviour: the app
// always mutates its in-memory array first, then calls saveJSON with
// the complete array, so a "replace the whole collection" PUT is the
// simplest, safest way to keep the database in sync.
// Fire-and-forget on purpose (like localStorage writes were instant),
// but any failure is logged to the console.
function saveJSON(key, value){
  fetch(`${API_BASE}/${key}`, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(value),
  }).catch((e) => {
    console.error(`Failed to save "${key}" to database:`, e);
  });
}
function uid(){
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
}
function fmtMoney(n){
  const v = Number(n) || 0;
  return 'Rs ' + v.toLocaleString('en-PK', { maximumFractionDigits: 0 });
}
function fmtDate(d){
  const dt = new Date(d);
  if (isNaN(dt)) return d;
  return dt.toLocaleDateString('en-GB', { day:'2-digit', month:'short', year:'numeric' });
}
function fmtDateTime(iso){
  const dt = new Date(iso);
  return dt.toLocaleDateString('en-GB', { day:'2-digit', month:'short' }) + ' · ' +
         dt.toLocaleTimeString('en-GB', { hour:'2-digit', minute:'2-digit' });
}

// Fills a <select> with plain-string options from a configurable list
// (item categories, expense categories, order statuses, roles, ...).
// Keeps the element's current value selected if it's still in the list.
function populateSelect(selectEl, values){
  const prev = selectEl.value;
  selectEl.innerHTML = (values || []).map(v => `<option value="${escapeHTML(v)}">${escapeHTML(v)}</option>`).join('');
  if (values && values.includes(prev)) selectEl.value = prev;
}

/* ---------------------------------------------------------------
   AVATARS  (per-user profile photo, shown wherever a user's circle
   is displayed — sidebar, Users table, User modal). Stored as a
   small compressed base64 data URL right on the user document, so
   no extra file storage/collection is needed.
   --------------------------------------------------------------- */
function initials(name){
  if (!name) return '?';
  const parts = name.trim().split(/\s+/);
  return ((parts[0]?.[0] || '') + (parts[1]?.[0] || '')).toUpperCase() || name[0].toUpperCase();
}

// Returns HTML for a circular avatar: the user's photo if they have one,
// otherwise their initials on a gold ring (matching the app's look).
function avatarHTML(user, extraClass){
  const cls = `avatar-circle${extraClass ? ' ' + extraClass : ''}`;
  if (user && user.avatar){
    return `<span class="${cls}"><img src="${user.avatar}" alt="${escapeHTML(user.name || '')}"></span>`;
  }
  return `<span class="${cls}">${escapeHTML(initials(user && user.name))}</span>`;
}

// Reads an <input type="file"> image, downsizes it to at most
// maxDim×maxDim (keeping aspect ratio) and re-encodes as JPEG, so
// even a large phone photo turns into a small, DB-friendly data URL.
function fileToResizedDataURL(file, maxDim){
  return new Promise((resolve, reject) => {
    if (!file || !file.type.startsWith('image/')){
      reject(new Error('Please choose an image file.'));
      return;
    }
    const reader = new FileReader();
    reader.onerror = () => reject(new Error('Could not read that file.'));
    reader.onload = () => {
      const img = new Image();
      img.onerror = () => reject(new Error('Could not read that image.'));
      img.onload = () => {
        const scale = Math.min(1, maxDim / Math.max(img.width, img.height));
        const w = Math.round(img.width * scale);
        const h = Math.round(img.height * scale);
        const canvas = document.createElement('canvas');
        canvas.width = w;
        canvas.height = h;
        canvas.getContext('2d').drawImage(img, 0, 0, w, h);
        resolve(canvas.toDataURL('image/jpeg', 0.85));
      };
      img.src = reader.result;
    };
    reader.readAsDataURL(file);
  });
}

/* ---------------------------------------------------------------
   State
   --------------------------------------------------------------- */
// These start empty and get filled in by loadAllData() (called near the
// bottom of this file) once the database has answered. Every function in
// this file that reads/writes them keeps working unchanged, because they
// are the same top-level "let" bindings — only *when* they get populated
// changed (async, from the API, instead of instantly from localStorage).
let items = [];
let orders = [];
let expenses = [];
let history = [];
let invoices = [];
let users = [];
let tasks = [];
let stockMoves = [];
let passwordRequests = [];
let photoRequests = [];
// The configurable lists (categories/statuses/priorities/roles). Filled by
// loadAllData() below; falls back to DEFAULT_SETTINGS if the database has
// nothing yet or the request fails, so the app never ends up with empty
// dropdowns.
let settings = DEFAULT_SETTINGS;

async function loadSettings(){
  try{
    const res = await fetch(`${API_BASE}/settings`);
    if (!res.ok) throw new Error('Bad response: ' + res.status);
    const data = await res.json();
    // Merge over defaults so any list missing from an older/partial
    // database record still falls back sensibly instead of being empty.
    return { ...DEFAULT_SETTINGS, ...data };
  }catch(e){
    console.error('Failed to load settings from database:', e);
    return DEFAULT_SETTINGS;
  }
}
function saveSettings(){
  fetch(`${API_BASE}/settings`, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(settings),
  }).catch((e) => {
    console.error('Failed to save settings to database:', e);
  });
}

// Looks up a role's permission flags by name. Returns a safe "no access"
// default if the role was deleted from Settings but is still stuck on an
// old user record, so the app never crashes on a missing role.
function getRoleDef(roleName){
  return (settings.roles || []).find(r => r.name === roleName) || { name: roleName, fullAccess: false, isOwner: false };
}

// Fetches every collection from the database in parallel and fills the
// arrays above. Must finish before ensureDefaultUsers()/showApp()/showLogin()
// run, so it's awaited at the bottom of this file.
async function loadAllData(){
  [items, orders, expenses, history, invoices, users, tasks, stockMoves, passwordRequests, photoRequests, settings] = await Promise.all([
    loadJSON(STORAGE_KEYS.ITEMS, []),
    loadJSON(STORAGE_KEYS.ORDERS, []),
    loadJSON(STORAGE_KEYS.EXPENSES, []),
    loadJSON(STORAGE_KEYS.HISTORY, []),
    loadJSON(STORAGE_KEYS.INVOICES, []),
    loadJSON(STORAGE_KEYS.USERS, []),
    loadJSON(STORAGE_KEYS.TASKS, []),
    loadJSON(STORAGE_KEYS.STOCK_LEDGER, []),
    loadJSON(STORAGE_KEYS.PASSWORD_REQUESTS, []),
    loadJSON(STORAGE_KEYS.PHOTO_REQUESTS, []),
    loadSettings(),
  ]);
}
