function logHistory(text, type){
  history.unshift({ id: uid(), text, type: type || 'neutral', time: new Date().toISOString() });
  history = history.slice(0, 300); // keep it bounded
  saveJSON(STORAGE_KEYS.HISTORY, history);
}

