const todayDateEl = document.getElementById('todayDate');
todayDateEl.textContent = new Date().toLocaleDateString('en-GB', { weekday:'long', day:'2-digit', month:'long', year:'numeric' });

function computeTotals(){
  const totalIncome = orders
    .filter(o => o.status === 'Delivered')
    .reduce((sum, o) => sum + Number(o.amount), 0);
  const totalExpense = expenses.reduce((sum, e) => sum + Number(e.amount), 0);
  const net = totalIncome - totalExpense;
  const pending = orders.filter(o => o.status === 'Pending').length;
  const lowStock = items.filter(i => Number(i.stock) <= LOW_STOCK_THRESHOLD).length;
  return { totalIncome, totalExpense, net, pending, totalOrders: orders.length, totalItems: items.length, lowStock };
}

function renderDashboard(){
  const { totalIncome, totalExpense, net, pending, totalOrders, totalItems, lowStock } = computeTotals();
  document.getElementById('statIncome').textContent = fmtMoney(totalIncome);
  document.getElementById('statExpense').textContent = fmtMoney(totalExpense);

  const statNet = document.getElementById('statNet');
  statNet.textContent = fmtMoney(net);
  statNet.style.color = net >= 0 ? 'var(--income)' : 'var(--expense)';
  document.getElementById('statNetFoot').textContent = net >= 0 ? 'Profit' : 'Loss';

  document.getElementById('statOrders').textContent = totalOrders;
  document.getElementById('statOrdersFoot').textContent = pending + ' pending';

  document.getElementById('statItems').textContent = totalItems;
  document.getElementById('statItemsFoot').textContent = lowStock + ' low stock';

  renderStockPanel();
  renderRecentActivity();
  drawDashboardCharts();
}

function renderRecentActivity(){
  const list = document.getElementById('recentActivity');
  const recent = history.slice(0, 8);
  list.innerHTML = '';
  if (recent.length === 0){
    list.innerHTML = '<li><span class="hist-text">No activity yet.</span></li>';
    return;
  }
  recent.forEach(h => {
    const li = document.createElement('li');
    li.innerHTML = `<span class="hist-text">${escapeHTML(h.text)}</span><span class="hist-time">${fmtDateTime(h.time)}</span>`;
    list.appendChild(li);
  });
}

function computeMonthlyBuckets(){
  const months = [];
  const now = new Date();
  for (let i = 5; i >= 0; i--){
    const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
    months.push({ key: d.getFullYear() + '-' + d.getMonth(), label: d.toLocaleDateString('en-GB', { month:'short' }), income:0, expense:0 });
  }
  const findBucket = (dateStr) => {
    const d = new Date(dateStr);
    const key = d.getFullYear() + '-' + d.getMonth();
    return months.find(m => m.key === key);
  };
  orders.filter(o => o.status === 'Delivered').forEach(o => {
    const b = findBucket(o.date);
    if (b) b.income += Number(o.amount);
  });
  expenses.forEach(e => {
    const b = findBucket(e.date);
    if (b) b.expense += Number(e.amount);
  });
  months.forEach(m => { m.profit = m.income - m.expense; });
  return months;
}

function drawSingleMetricChart(canvasId, months, valueKey, opts){
  const canvas = document.getElementById(canvasId);
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const dpr = window.devicePixelRatio || 1;
  const width = canvas.clientWidth;
  const height = canvas.clientHeight || 120;
  canvas.width = width * dpr;
  canvas.height = height * dpr;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, width, height);

  const allowNegative = !!opts.allowNegative;
  const padding = { top: 10, bottom: 24, left: 10, right: 10 };
  const chartH = height - padding.top - padding.bottom;
  const chartW = width - padding.left - padding.right;
  const groupW = chartW / months.length;
  const barW = groupW * 0.42;

  const values = months.map(m => m[valueKey]);
  const maxVal = Math.max(1, ...values.map(v => Math.abs(v)));
  const zeroY = allowNegative ? padding.top + chartH / 2 : padding.top + chartH;
  const halfH = allowNegative ? chartH / 2 - 4 : chartH;

  // zero baseline for negative-capable charts
  if (allowNegative){
    ctx.strokeStyle = '#2A2E38';
    ctx.beginPath();
    ctx.moveTo(padding.left, zeroY);
    ctx.lineTo(width - padding.right, zeroY);
    ctx.stroke();
  }

  ctx.font = '11px Inter, sans-serif';
  ctx.textAlign = 'center';

  months.forEach((m, i) => {
    const groupX = padding.left + i * groupW + groupW / 2;
    const val = m[valueKey];
    const barH = (Math.abs(val) / maxVal) * halfH;
    const color = allowNegative ? (val >= 0 ? '#4CAF7D' : '#E0665A') : opts.color;

    ctx.fillStyle = color;
    if (val >= 0){
      roundRect(ctx, groupX - barW / 2, zeroY - barH, barW, barH, 3);
    } else {
      roundRect(ctx, groupX - barW / 2, zeroY, barW, barH, 3);
    }
    ctx.fill();

    ctx.fillStyle = '#8A8F98';
    ctx.fillText(m.label, groupX, height - 6);
  });
}

function drawDashboardCharts(){
  const months = computeMonthlyBuckets();
  drawSingleMetricChart('incomeChart', months, 'income', { color:'#4CAF7D' });
  drawSingleMetricChart('expenseChart', months, 'expense', { color:'#E0665A' });
  drawSingleMetricChart('profitChart', months, 'profit', { allowNegative:true });
}

function roundRect(ctx, x, y, w, h, r){
  if (h < 0) { y += h; h = Math.abs(h); }
  h = Math.max(h, 1);
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

/* ---------------------------------------------------------------
   STOCK MANAGEMENT (Dashboard)
   Every stock-in / stock-out movement is logged with its own date
   (any date can be chosen — past or present) and immediately syncs
   the item's live "stock" value used across Items, Orders & Invoices.
   --------------------------------------------------------------- */
const stockMoveForm = document.getElementById('stockMoveForm');
const stockMoveFormWrap = document.getElementById('stockMoveFormWrap');
const stockMoveItemSelect = document.getElementById('stockMoveItem');
const stockMoveDateInput = document.getElementById('stockMoveDate');
const stockMoveMsg = document.getElementById('stockMoveMsg');
const stockMovesBody = document.getElementById('stockMovesBody');
const stockMovesEmpty = document.getElementById('stockMovesEmpty');

// Default the date picker to today; user is free to change it to log
// stock for any specific past (or future) date.
if (stockMoveDateInput) stockMoveDateInput.value = new Date().toISOString().slice(0, 10);

function computeStockTotals(){
  const totalIn = stockMoves.filter(m => m.type === 'in').reduce((s, m) => s + (Number(m.qty) || 0), 0);
  const totalOut = stockMoves.filter(m => m.type === 'out').reduce((s, m) => s + (Number(m.qty) || 0), 0);
  const remaining = items.reduce((s, i) => s + (Number(i.stock) || 0), 0);
  return { totalIn, totalOut, remaining };
}

function syncStockMoveItemSelect(){
  if (!stockMoveItemSelect) return;
  const prevVal = stockMoveItemSelect.value;
  stockMoveItemSelect.innerHTML = items.length
    ? items.map(i => `<option value="${i.id}">${escapeHTML(i.name)} — ${i.stock} in stock</option>`).join('')
    : '<option value="">No items yet — add one first</option>';
  if (items.some(i => i.id === prevVal)) stockMoveItemSelect.value = prevVal;
}

function renderStockPanel(){
  const { totalIn, totalOut, remaining } = computeStockTotals();
  document.getElementById('stockInTotal').textContent = totalIn.toLocaleString('en-PK');
  document.getElementById('stockOutTotal').textContent = totalOut.toLocaleString('en-PK');
  document.getElementById('stockRemainingTotal').textContent = remaining.toLocaleString('en-PK');

  syncStockMoveItemSelect();

  const canEditStock = canEdit('items');
  if (stockMoveFormWrap) stockMoveFormWrap.classList.toggle('hidden', !canEditStock);

  const sorted = [...stockMoves].sort((a, b) =>
    new Date(b.date) - new Date(a.date) || new Date(b.createdAt) - new Date(a.createdAt)
  );

  stockMovesBody.innerHTML = '';
  stockMovesEmpty.classList.toggle('hidden', sorted.length > 0);

  sorted.forEach(m => {
    const tr = document.createElement('tr');
    tr.innerHTML = `
      <td>${fmtDate(m.date)}</td>
      <td>${escapeHTML(m.itemName)}</td>
      <td><span class="stock-move-pill stock-move-${m.type}">${m.type === 'in' ? 'Stock In' : 'Stock Out'}</span></td>
      <td>${m.qty}</td>
      <td>${m.remainingAfter}</td>
      <td>${m.note ? escapeHTML(m.note) : '—'}</td>
      <td>
        ${canEditStock ? `<div class="row-actions">
          <button class="icon-btn danger" data-stock-del="${m.id}">Delete</button>
        </div>` : ''}
      </td>`;
    stockMovesBody.appendChild(tr);
  });

  stockMovesBody.querySelectorAll('[data-stock-del]').forEach(btn => {
    btn.addEventListener('click', () => {
      const move = stockMoves.find(m => m.id === btn.dataset.stockDel);
      if (!move) return;
      confirmAction(
        'Delete this stock entry?',
        `This reverses the stock ${move.type === 'in' ? 'increase' : 'decrease'} of ${move.qty} unit(s) for "${move.itemName}".`,
        () => {
          const item = items.find(i => i.id === move.itemId);
          if (item){
            item.stock = move.type === 'in'
              ? Math.max(0, Number(item.stock) - move.qty)
              : Number(item.stock) + move.qty;
            saveJSON(STORAGE_KEYS.ITEMS, items);
          }
          stockMoves = stockMoves.filter(m => m.id !== move.id);
          saveJSON(STORAGE_KEYS.STOCK_LEDGER, stockMoves);
          logHistory(`Stock entry deleted — ${move.itemName} (${move.qty} units)`, 'stock');
          renderDashboard();
          renderItems();
          syncItemsDatalist();
        }
      );
    });
  });
}

if (stockMoveForm){
  stockMoveForm.addEventListener('submit', (e) => {
    e.preventDefault();
    if (!canEdit('items')) return;

    const itemId = stockMoveItemSelect.value;
    const type = document.getElementById('stockMoveType').value;
    const qty = parseInt(document.getElementById('stockMoveQty').value, 10);
    const date = stockMoveDateInput.value;
    const note = document.getElementById('stockMoveNote').value.trim();

    const item = items.find(i => i.id === itemId);
    if (!item){
      stockMoveMsg.textContent = 'Please select a valid item (add one on the Items page first).';
      stockMoveMsg.className = 'form-msg err';
      return;
    }
    if (!qty || qty <= 0){
      stockMoveMsg.textContent = 'Quantity must be at least 1.';
      stockMoveMsg.className = 'form-msg err';
      return;
    }
    if (!date){
      stockMoveMsg.textContent = 'Please pick a date for this stock movement.';
      stockMoveMsg.className = 'form-msg err';
      return;
    }
    if (type === 'out' && Number(item.stock) < qty){
      stockMoveMsg.textContent = `Not enough stock — "${item.name}" only has ${item.stock} left.`;
      stockMoveMsg.className = 'form-msg err';
      return;
    }

    item.stock = type === 'in'
      ? Number(item.stock) + qty
      : Math.max(0, Number(item.stock) - qty);
    saveJSON(STORAGE_KEYS.ITEMS, items);

    stockMoves.unshift({
      id: uid(),
      itemId: item.id,
      itemName: item.name,
      type,
      qty,
      date,
      note,
      remainingAfter: item.stock,
      createdAt: new Date().toISOString(),
    });
    saveJSON(STORAGE_KEYS.STOCK_LEDGER, stockMoves);

    logHistory(`Stock ${type === 'in' ? 'in' : 'out'} — ${item.name} (${qty} units, ${fmtDate(date)})`, type === 'in' ? 'stock-in' : 'stock-out');

    stockMoveMsg.textContent = `Recorded. ${item.name} now has ${item.stock} in stock.`;
    stockMoveMsg.className = 'form-msg ok';
    document.getElementById('stockMoveQty').value = '';
    document.getElementById('stockMoveNote').value = '';

    renderDashboard();
    renderItems();
    syncItemsDatalist();
  });
}

/* ---------------------------------------------------------------
   ITEMS
   --------------------------------------------------------------- */
const itemsTableBody = document.getElementById('itemsTableBody');
const itemsEmpty = document.getElementById('itemsEmpty');
const itemCountEl = document.getElementById('itemCount');
const itemModal = document.getElementById('itemModal');
const itemForm = document.getElementById('itemForm');
const itemModalTitle = document.getElementById('itemModalTitle');
const itemSearchInput = document.getElementById('itemSearch');

document.getElementById('addItemBtn').addEventListener('click', () => {
  if (!canEdit('items')) return;
  openItemModal();
});
document.getElementById('itemCancelBtn').addEventListener('click', () => closeModal(itemModal));

itemSearchInput.addEventListener('input', () => {
  itemSearchTerm = itemSearchInput.value.trim().toLowerCase();
  renderItems();
});

function openItemModal(item){
  itemForm.reset();
  document.getElementById('itemId').value = item ? item.id : '';
  itemModalTitle.textContent = item ? 'Edit Item' : 'New Item';
  populateSelect(document.getElementById('itemCategory'), settings.itemCategories);
  if (item){
    document.getElementById('itemName').value = item.name;
    document.getElementById('itemCategory').value = item.category;
    document.getElementById('itemPrice').value = item.price;
    document.getElementById('itemStock').value = item.stock;
    document.getElementById('itemStatus').value = item.status;
  } else {
    document.getElementById('itemStatus').value = 'Active';
  }
  itemModal.classList.remove('hidden');
}

itemForm.addEventListener('submit', (e) => {
  e.preventDefault();
  if (!canEdit('items')) return;
  const id = document.getElementById('itemId').value;
  const data = {
    name: document.getElementById('itemName').value.trim(),
    category: document.getElementById('itemCategory').value,
    price: parseFloat(document.getElementById('itemPrice').value),
    stock: parseInt(document.getElementById('itemStock').value, 10),
    status: document.getElementById('itemStatus').value,
  };
  if (id){
    const idx = items.findIndex(i => i.id === id);
    if (idx > -1){
      items[idx] = { ...items[idx], ...data };
      logHistory(`Item updated — ${data.name}`, 'neutral');
    }
  } else {
    items.unshift({ id: uid(), ...data });
    logHistory(`New item added — ${data.name} (${fmtMoney(data.price)})`, 'neutral');
  }
  saveJSON(STORAGE_KEYS.ITEMS, items);
  closeModal(itemModal);
  renderItems();
  syncItemsDatalist();
  renderDashboard();
});

function renderItems(){
  const term = itemSearchTerm;
  const filtered = term
    ? items.filter(i => i.name.toLowerCase().includes(term) || i.category.toLowerCase().includes(term))
    : items;

  itemsTableBody.innerHTML = '';
  itemsEmpty.classList.toggle('hidden', filtered.length > 0);
  itemsEmpty.textContent = term && items.length > 0
    ? 'No items match your search.'
    : 'No items yet. Click "New Item" to add your first one.';

  itemCountEl.textContent = term
    ? `${filtered.length} of ${items.length} items`
    : `${items.length} item${items.length === 1 ? '' : 's'}`;

  const canEditItems = canEdit('items');

  filtered.forEach(i => {
    const tr = document.createElement('tr');
    const lowStock = Number(i.stock) <= LOW_STOCK_THRESHOLD;
    tr.innerHTML = `
      <td>${escapeHTML(i.name)}</td>
      <td>${escapeHTML(i.category)}</td>
      <td>${fmtMoney(i.price)}</td>
      <td class="${lowStock ? 'low-stock' : ''}">${i.stock}${lowStock ? ' ⚠' : ''}</td>
      <td><span class="status-pill status-${i.status}">${i.status}</span></td>
      <td>
        ${canEditItems ? `<div class="row-actions">
          <button class="icon-btn" data-edit="${i.id}">Edit</button>
          <button class="icon-btn danger" data-del="${i.id}">Delete</button>
        </div>` : ''}
      </td>`;
    itemsTableBody.appendChild(tr);
  });

  itemsTableBody.querySelectorAll('[data-edit]').forEach(btn => {
    btn.addEventListener('click', () => {
      const item = items.find(i => i.id === btn.dataset.edit);
      if (item) openItemModal(item);
    });
  });
  itemsTableBody.querySelectorAll('[data-del]').forEach(btn => {
    btn.addEventListener('click', () => {
      const item = items.find(i => i.id === btn.dataset.del);
      confirmAction(
        'Delete this item?',
        `This will permanently remove "${item ? item.name : ''}" from the catalog.`,
        () => {
          items = items.filter(i => i.id !== btn.dataset.del);
          saveJSON(STORAGE_KEYS.ITEMS, items);
          logHistory(`Item deleted — ${item ? item.name : ''}`, 'neutral');
          renderItems();
          syncItemsDatalist();
          renderDashboard();
        }
      );
    });
  });
}

function syncItemsDatalist(){
  const datalist = document.getElementById('itemsDatalist');
  if (!datalist) return;
  datalist.innerHTML = items.map(i => `<option value="${escapeHTML(i.name)}"></option>`).join('');
}

/* ---------------------------------------------------------------
   ORDERS
   --------------------------------------------------------------- */
const ordersTableBody = document.getElementById('ordersTableBody');
const ordersEmpty = document.getElementById('ordersEmpty');
const orderModal = document.getElementById('orderModal');
const orderForm = document.getElementById('orderForm');
const orderModalTitle = document.getElementById('orderModalTitle');

document.getElementById('addOrderBtn').addEventListener('click', () => {
  if (!canEdit('orders')) return;
  openOrderModal();
});
document.getElementById('orderCancelBtn').addEventListener('click', () => closeModal(orderModal));

const orderSearchInput = document.getElementById('orderSearch');
const orderCountEl = document.getElementById('orderCount');
orderSearchInput.addEventListener('input', () => {
  orderSearchTerm = orderSearchInput.value.trim().toLowerCase();
  renderOrders();
});

// Auto-fetch the Amount from the matching Item's price when a Service/Item
// is picked (or typed exactly). If the user has manually edited the Amount
// field themselves, we stop overwriting it (same "touched" pattern used on
// the Invoice line items).
const orderItemInput = document.getElementById('orderItem');
const orderAmountInput = document.getElementById('orderAmount');
orderItemInput.addEventListener('input', () => {
  const match = items.find(i => i.name.toLowerCase() === orderItemInput.value.trim().toLowerCase());
  if (match && !orderAmountInput.dataset.touched){
    orderAmountInput.value = match.price;
  }
});
orderAmountInput.addEventListener('input', () => { orderAmountInput.dataset.touched = '1'; });

function openOrderModal(order){
  orderForm.reset();
  delete orderAmountInput.dataset.touched;
  document.getElementById('orderId').value = order ? order.id : '';
  orderModalTitle.textContent = order ? 'Edit Order' : 'New Order';
  populateSelect(document.getElementById('orderStatus'), settings.orderStatuses);
  if (order){
    document.getElementById('orderCustomer').value = order.customer;
    document.getElementById('orderContact').value = order.contact || '';
    document.getElementById('orderEmail').value = order.email || '';
    document.getElementById('orderItem').value = order.item;
    document.getElementById('orderAmount').value = order.amount;
    document.getElementById('orderStatus').value = order.status;
    document.getElementById('orderDate').value = order.date;
    // Editing an existing order: treat amount as already set by the user
    // so re-opening the item dropdown doesn't silently overwrite it.
    orderAmountInput.dataset.touched = '1';
  } else {
    document.getElementById('orderDate').value = new Date().toISOString().slice(0,10);
  }
  orderModal.classList.remove('hidden');
}

orderForm.addEventListener('submit', (e) => {
  e.preventDefault();
  if (!canEdit('orders')) return;
  const id = document.getElementById('orderId').value;
  const data = {
    customer: document.getElementById('orderCustomer').value.trim(),
    contact: document.getElementById('orderContact').value.trim(),
    email: document.getElementById('orderEmail').value.trim(),
    item: document.getElementById('orderItem').value.trim(),
    amount: parseFloat(document.getElementById('orderAmount').value),
    status: document.getElementById('orderStatus').value,
    date: document.getElementById('orderDate').value,
  };
  if (id){
    const idx = orders.findIndex(o => o.id === id);
    if (idx > -1){
      orders[idx] = { ...orders[idx], ...data };
      logHistory(`Order updated — ${data.customer} (${fmtMoney(data.amount)})`, 'neutral');
    }
  } else {
    const newOrder = { id: uid(), ...data };
    orders.unshift(newOrder);
    logHistory(`New order — ${data.customer} (${fmtMoney(data.amount)})`, data.status === 'Delivered' ? 'income' : 'neutral');
  }
  saveJSON(STORAGE_KEYS.ORDERS, orders);
  closeModal(orderModal);
  renderOrders();
  renderDashboard();
});

function renderOrders(){
  const term = orderSearchTerm;
  const filtered = term
    ? orders.filter(o =>
        o.customer.toLowerCase().includes(term) ||
        o.item.toLowerCase().includes(term) ||
        (o.contact || '').toLowerCase().includes(term) ||
        (o.email || '').toLowerCase().includes(term))
    : orders;

  ordersTableBody.innerHTML = '';
  ordersEmpty.classList.toggle('hidden', filtered.length > 0);
  ordersEmpty.textContent = term && orders.length > 0
    ? 'No orders match your search.'
    : 'No orders yet. Click "New Order" to add your first one.';

  orderCountEl.textContent = term
    ? `${filtered.length} of ${orders.length} orders`
    : `${orders.length} order${orders.length === 1 ? '' : 's'}`;

  const canEditOrders = canEdit('orders');

  filtered.forEach(o => {
    const tr = document.createElement('tr');
    tr.innerHTML = `
      <td>#${o.id.slice(-6).toUpperCase()}</td>
      <td>${escapeHTML(o.customer)}</td>
      <td>${escapeHTML(o.contact || '—')}</td>
      <td>${escapeHTML(o.email || '—')}</td>
      <td>${escapeHTML(o.item)}</td>
      <td>${fmtMoney(o.amount)}</td>
      <td><span class="status-pill status-${o.status}">${o.status}</span></td>
      <td>${fmtDate(o.date)}</td>
      <td>
        ${canEditOrders ? `<div class="row-actions">
          <button class="icon-btn" data-edit="${o.id}">Edit</button>
          <button class="icon-btn danger" data-del="${o.id}">Delete</button>
        </div>` : ''}
      </td>`;
    ordersTableBody.appendChild(tr);
  });

  ordersTableBody.querySelectorAll('[data-edit]').forEach(btn => {
    btn.addEventListener('click', () => {
      const order = orders.find(o => o.id === btn.dataset.edit);
      if (order) openOrderModal(order);
    });
  });
  ordersTableBody.querySelectorAll('[data-del]').forEach(btn => {
    btn.addEventListener('click', () => {
      const order = orders.find(o => o.id === btn.dataset.del);
      confirmAction(
        'Delete this order?',
        `This will permanently remove the order for "${order ? order.customer : ''}".`,
        () => {
          orders = orders.filter(o => o.id !== btn.dataset.del);
          saveJSON(STORAGE_KEYS.ORDERS, orders);
          logHistory(`Order deleted — ${order ? order.customer : ''}`, 'expense');
          renderOrders();
          renderDashboard();
        }
      );
    });
  });
}

/* ---------------------------------------------------------------
   SALES / INVOICES
   --------------------------------------------------------------- */
const invoicesTableBody = document.getElementById('invoicesTableBody');
const invoicesEmpty = document.getElementById('invoicesEmpty');
const invoiceCountEl = document.getElementById('invoiceCount');
const invoiceSearchInput = document.getElementById('invoiceSearch');
const invoiceModal = document.getElementById('invoiceModal');
const invoiceForm = document.getElementById('invoiceForm');
const invoiceModalTitle = document.getElementById('invoiceModalTitle');
const lineItemsBody = document.getElementById('lineItemsBody');

let invoiceSubmitMode = 'save'; // 'save' | 'print'

document.getElementById('addInvoiceBtn').addEventListener('click', () => {
  if (!canEdit('invoices')) return;
  openInvoiceModal();
});
document.getElementById('invoiceCancelBtn').addEventListener('click', () => closeModal(invoiceModal));
document.getElementById('addLineItemBtn').addEventListener('click', () => { addLineItemRow(); recalcInvoiceTotals(); });

invoiceSearchInput.addEventListener('input', () => {
  invoiceSearchTerm = invoiceSearchInput.value.trim().toLowerCase();
  renderInvoices();
});

document.querySelector('#invoiceForm button[type="submit"].btn-gold').addEventListener('click', () => { invoiceSubmitMode = 'save'; });
document.getElementById('saveAndPrintBtn').addEventListener('click', () => { invoiceSubmitMode = 'print'; });

function generateTrackingId(){
  const n = invoices.length + 1;
  return 'EDH-' + String(n).padStart(5, '0') + '-' + Date.now().toString(36).slice(-4).toUpperCase();
}

function addLineItemRow(item){
  lineItemCounter++;
  const rowId = 'li' + lineItemCounter;
  const tr = document.createElement('tr');
  tr.dataset.rowId = rowId;
  tr.innerHTML = `
    <td class="li-index">${lineItemsBody.children.length + 1}</td>
    <td><input type="text" class="li-product" list="lineItemsDatalist" placeholder="Type or pick an item" value="${item ? escapeHTML(item.product) : ''}"></td>
    <td><input type="number" class="li-qty li-num-input" min="1" step="1" value="${item ? item.qty : 1}"></td>
    <td><input type="number" class="li-price li-num-input" min="0" step="0.01" value="${item ? item.price : 0}"></td>
    <td><input type="text" class="li-total li-num-input" readonly value="${fmtMoney(item ? item.qty * item.price : 0)}"></td>
    <td><button type="button" class="li-remove-btn">✕</button></td>`;
  lineItemsBody.appendChild(tr);

  const productInput = tr.querySelector('.li-product');
  const qtyInput = tr.querySelector('.li-qty');
  const priceInput = tr.querySelector('.li-price');

  productInput.addEventListener('change', () => {
    const match = items.find(i => i.name.toLowerCase() === productInput.value.trim().toLowerCase());
    if (match && (!priceInput.dataset.touched)){
      priceInput.value = match.price;
    }
    recalcInvoiceTotals();
  });
  priceInput.addEventListener('input', () => { priceInput.dataset.touched = '1'; recalcInvoiceTotals(); });
  qtyInput.addEventListener('input', recalcInvoiceTotals);
  tr.querySelector('.li-remove-btn').addEventListener('click', () => {
    tr.remove();
    renumberLineItems();
    recalcInvoiceTotals();
  });
}

function renumberLineItems(){
  [...lineItemsBody.children].forEach((tr, idx) => {
    tr.querySelector('.li-index').textContent = idx + 1;
  });
}

function recalcInvoiceTotals(){
  let subtotal = 0;
  [...lineItemsBody.children].forEach(tr => {
    const qty = parseFloat(tr.querySelector('.li-qty').value) || 0;
    const price = parseFloat(tr.querySelector('.li-price').value) || 0;
    const total = qty * price;
    tr.querySelector('.li-total').value = fmtMoney(total);
    subtotal += total;
  });
  document.getElementById('invoiceSubtotal').value = fmtMoney(subtotal);
  const paid = parseFloat(document.getElementById('invoicePaid').value) || 0;
  const pending = Math.max(subtotal - paid, 0);
  document.getElementById('invoicePending').value = fmtMoney(pending);
  return { subtotal, paid, pending };
}

document.getElementById('invoicePaid').addEventListener('input', recalcInvoiceTotals);

function syncLineItemsDatalist(){
  const datalist = document.getElementById('lineItemsDatalist');
  if (!datalist) return;
  datalist.innerHTML = items.map(i => `<option value="${escapeHTML(i.name)}"></option>`).join('');
}

function openInvoiceModal(invoice){
  invoiceForm.reset();
  lineItemsBody.innerHTML = '';
  document.getElementById('invoiceId').value = invoice ? invoice.id : '';
  invoiceModalTitle.textContent = invoice ? 'Edit Invoice' : 'New Invoice';
  syncLineItemsDatalist();

  if (invoice){
    document.getElementById('invoiceTrackingId').value = invoice.trackingId;
    document.getElementById('invoiceDate').value = invoice.date;
    document.getElementById('invoiceCustomer').value = invoice.customer;
    document.getElementById('invoiceContact').value = invoice.contact;
    document.getElementById('invoiceEmail').value = invoice.email;
    document.getElementById('invoicePaid').value = invoice.paid;
    invoice.lineItems.forEach(li => addLineItemRow(li));
    renderInvoiceStatusRadios(invoice.status);
  } else {
    document.getElementById('invoiceTrackingId').value = generateTrackingId();
    document.getElementById('invoiceDate').value = new Date().toISOString().slice(0,10);
    addLineItemRow();
    renderInvoiceStatusRadios(settings.orderStatuses[1] || settings.orderStatuses[0]);
  }
  recalcInvoiceTotals();
  invoiceModal.classList.remove('hidden');
}

// Builds the "Order Status" radio pills from the same configurable
// orderStatuses list used on the Orders form, so adding/removing a status
// in Settings → Manage Lists updates both places at once.
function renderInvoiceStatusRadios(selectedValue){
  const group = document.getElementById('invoiceStatusGroup');
  group.innerHTML = (settings.orderStatuses || []).map(s => `
    <label class="radio-pill">
      <input type="radio" name="invoiceStatus" value="${escapeHTML(s)}" ${s === selectedValue ? 'checked' : ''}>
      ${escapeHTML(s)}
    </label>
  `).join('');
}

invoiceForm.addEventListener('submit', (e) => {
  e.preventDefault();
  if (!canEdit('invoices')) return;
  const id = document.getElementById('invoiceId').value;
  const lineItems = [...lineItemsBody.children].map(tr => ({
    product: tr.querySelector('.li-product').value.trim(),
    qty: parseFloat(tr.querySelector('.li-qty').value) || 0,
    price: parseFloat(tr.querySelector('.li-price').value) || 0,
  })).filter(li => li.product);

  if (lineItems.length === 0){
    alert('Please add at least one product or service.');
    return;
  }

  const { subtotal, paid, pending } = recalcInvoiceTotals();
  const status = document.querySelector('input[name="invoiceStatus"]:checked').value;

  const data = {
    trackingId: document.getElementById('invoiceTrackingId').value,
    date: document.getElementById('invoiceDate').value,
    customer: document.getElementById('invoiceCustomer').value.trim(),
    contact: document.getElementById('invoiceContact').value.trim(),
    email: document.getElementById('invoiceEmail').value.trim(),
    lineItems,
    subtotal,
    paid,
    pending,
    status,
  };

  if (id){
    const idx = invoices.findIndex(i => i.id === id);
    if (idx > -1){
      invoices[idx] = { ...invoices[idx], ...data };
      logHistory(`Invoice updated — ${data.trackingId} (${data.customer})`, 'neutral');
    }
  } else {
    invoices.unshift({ id: uid(), ...data });
    logHistory(`New invoice created — ${data.trackingId} (${data.customer}, ${fmtMoney(subtotal)})`, 'income');
    deductStockForLineItems(lineItems);
  }
  saveJSON(STORAGE_KEYS.INVOICES, invoices);

  const savedInvoice = invoices.find(i => i.trackingId === data.trackingId);
  closeModal(invoiceModal);
  renderInvoices();
  renderItems();
  syncItemsDatalist();
  renderDashboard();

  if (invoiceSubmitMode === 'print' && savedInvoice){
    printInvoice(savedInvoice);
  }
  invoiceSubmitMode = 'save';
});

function deductStockForLineItems(lineItems){
  let changed = false;
  lineItems.forEach(li => {
    const match = items.find(i => i.name.toLowerCase() === li.product.toLowerCase());
    if (match){
      match.stock = Math.max(0, Number(match.stock) - li.qty);
      changed = true;
    }
  });
  if (changed){
    saveJSON(STORAGE_KEYS.ITEMS, items);
    logHistory('Stock updated from invoice sale', 'neutral');
  }
}

function renderInvoices(){
  const term = invoiceSearchTerm;
  const filtered = term
    ? invoices.filter(i => i.customer.toLowerCase().includes(term) || i.trackingId.toLowerCase().includes(term))
    : invoices;

  invoicesTableBody.innerHTML = '';
  invoicesEmpty.classList.toggle('hidden', filtered.length > 0);
  invoicesEmpty.textContent = term && invoices.length > 0
    ? 'No invoices match your search.'
    : 'No invoices yet. Click "New Invoice" to create your first one.';

  invoiceCountEl.textContent = term
    ? `${filtered.length} of ${invoices.length} invoices`
    : `${invoices.length} invoice${invoices.length === 1 ? '' : 's'}`;

  const canEditInvoices = canEdit('invoices');

  filtered.forEach(inv => {
    const tr = document.createElement('tr');
    tr.innerHTML = `
      <td>${escapeHTML(inv.trackingId)}</td>
      <td>${escapeHTML(inv.customer)}</td>
      <td>${fmtDate(inv.date)}</td>
      <td>${fmtMoney(inv.subtotal)}</td>
      <td>${fmtMoney(inv.paid)}</td>
      <td>${fmtMoney(inv.pending)}</td>
      <td><span class="status-pill status-${inv.status}">${inv.status}</span></td>
      <td>
        <div class="row-actions">
          <button class="icon-btn" data-print="${inv.id}">Print</button>
          ${canEditInvoices ? `<button class="icon-btn" data-edit="${inv.id}">Edit</button>
          <button class="icon-btn danger" data-del="${inv.id}">Delete</button>` : ''}
        </div>
      </td>`;
    invoicesTableBody.appendChild(tr);
  });

  invoicesTableBody.querySelectorAll('[data-edit]').forEach(btn => {
    btn.addEventListener('click', () => {
      const inv = invoices.find(i => i.id === btn.dataset.edit);
      if (inv) openInvoiceModal(inv);
    });
  });
  invoicesTableBody.querySelectorAll('[data-print]').forEach(btn => {
    btn.addEventListener('click', () => {
      const inv = invoices.find(i => i.id === btn.dataset.print);
      if (inv) printInvoice(inv);
    });
  });
  invoicesTableBody.querySelectorAll('[data-del]').forEach(btn => {
    btn.addEventListener('click', () => {
      const inv = invoices.find(i => i.id === btn.dataset.del);
      confirmAction(
        'Delete this invoice?',
        `This will permanently remove invoice "${inv ? inv.trackingId : ''}".`,
        () => {
          invoices = invoices.filter(i => i.id !== btn.dataset.del);
          saveJSON(STORAGE_KEYS.INVOICES, invoices);
          logHistory(`Invoice deleted — ${inv ? inv.trackingId : ''}`, 'expense');
          renderInvoices();
        }
      );
    });
  });
}

function printInvoice(inv){
  const area = document.getElementById('printInvoiceArea');
  const rows = inv.lineItems.map((li, idx) => `
    <tr>
      <td>${idx + 1}</td>
      <td>${escapeHTML(li.product)}</td>
      <td class="num">${li.qty}</td>
      <td class="num">${fmtMoney(li.price)}</td>
      <td class="num">${fmtMoney(li.qty * li.price)}</td>
    </tr>`).join('');

  const statusBox = (label) => `<span><span class="pi-checkbox">${inv.status === label ? '✓' : ''}</span> ${label}</span>`;

  area.innerHTML = `
    <div id="piScaleWrap">
    <div class="pi-page" id="piPage">
      <div class="pi-header"></div>
      <div class="pi-header-content">
        <div class="pi-brand">
          <h1>${escapeHTML(BUSINESS_INFO.name)}</h1>
          <div class="pi-brand-line">📞 ${escapeHTML(BUSINESS_INFO.phone)}</div>
          <div class="pi-brand-line">✉ ${escapeHTML(BUSINESS_INFO.email)}</div>
          <div class="pi-brand-line">📍 ${escapeHTML(BUSINESS_INFO.address)}</div>
        </div>
        <div class="pi-logo"><img src="${LOGO_DATA_URI}" alt="Elite Digital Hub logo"></div>
      </div>
      <div class="pi-meta"><span>Tracking ID: <b>${escapeHTML(inv.trackingId)}</b></span></div>
      <div class="pi-fields">
        <div><b>Customer Name:</b> ${escapeHTML(inv.customer)}</div>
        <div><b>Contact:</b> ${escapeHTML(inv.contact || '')}</div>
        <div><b>Email:</b> ${escapeHTML(inv.email || '')}</div>
        <div><b>Order Date:</b> ${fmtDate(inv.date)}</div>
      </div>
      <table class="pi-table">
        <thead><tr><th>No</th><th>Product / Service</th><th class="num">Qty</th><th class="num">Price</th><th class="num">Total</th></tr></thead>
        <tbody>${rows}</tbody>
      </table>
      <table class="pi-summary">
        <thead><tr><th>Subtotal</th><th>Pending</th><th>Paid</th></tr></thead>
        <tbody><tr><td>${fmtMoney(inv.subtotal)}</td><td>${fmtMoney(inv.pending)}</td><td>${fmtMoney(inv.paid)}</td></tr></tbody>
      </table>
      <div class="pi-status">
        <b style="width:100%;display:block;margin-bottom:-6px;">Order Details</b>
      </div>
      <div class="pi-status">
        ${statusBox('Received')} ${statusBox('Pending')} ${statusBox('Delivered')}
      </div>
      <div class="pi-footer">
        <div>
          <b>Payment Policy:</b>
          ${escapeHTML(BUSINESS_INFO.paymentPolicy)}
        </div>
        <div>
          <b>Payment Methods:</b>
          ${BUSINESS_INFO.paymentMethods.map(m => `${escapeHTML(m.label)}:<br>${escapeHTML(m.value)}<br><br>`).join('')}
        </div>
      </div>
      <div class="pi-track">
        Track your order status by your tracking ID at:<br>
        <b>${escapeHTML(BUSINESS_INFO.trackingUrl)}</b>
      </div>
      <div class="pi-disclaimer">${escapeHTML(BUSINESS_INFO.disclaimer)}</div>
    </div>
    </div>`;

  // Auto-scale the invoice so it always prints within the top half of an
  // A4 sheet, regardless of how many line items it has.
  const page = document.getElementById('piPage');
  const wrap = document.getElementById('piScaleWrap');
  const pxPerMm = 96 / 25.4;
  const targetHeightPx = 130 * pxPerMm; // ~half of an A4 sheet, minus page margins
  const naturalWidth = page.offsetWidth;
  const naturalHeight = page.offsetHeight;

  if (naturalHeight > targetHeightPx){
    const scale = targetHeightPx / naturalHeight;
    page.style.transformOrigin = 'top left';
    page.style.transform = `scale(${scale})`;
    wrap.style.width = (naturalWidth * scale) + 'px';
    wrap.style.height = (naturalHeight * scale) + 'px';
  } else {
    page.style.transform = 'none';
    wrap.style.width = naturalWidth + 'px';
    wrap.style.height = naturalHeight + 'px';
  }

  window.print();
}

