const expensesTableBody = document.getElementById('expensesTableBody');
const expensesEmpty = document.getElementById('expensesEmpty');
const expenseModal = document.getElementById('expenseModal');
const expenseForm = document.getElementById('expenseForm');
const expenseModalTitle = document.getElementById('expenseModalTitle');

document.getElementById('addExpenseBtn').addEventListener('click', () => {
  if (!canEdit('expenses')) return;
  openExpenseModal();
});
document.getElementById('expenseCancelBtn').addEventListener('click', () => closeModal(expenseModal));

function openExpenseModal(expense){
  expenseForm.reset();
  document.getElementById('expenseId').value = expense ? expense.id : '';
  expenseModalTitle.textContent = expense ? 'Edit Expense' : 'New Expense';
  populateSelect(document.getElementById('expenseCategory'), settings.expenseCategories);
  if (expense){
    document.getElementById('expenseDesc').value = expense.desc;
    document.getElementById('expenseCategory').value = expense.category;
    document.getElementById('expenseAmount').value = expense.amount;
    document.getElementById('expenseDate').value = expense.date;
  } else {
    document.getElementById('expenseDate').value = new Date().toISOString().slice(0,10);
  }
  expenseModal.classList.remove('hidden');
}

expenseForm.addEventListener('submit', (e) => {
  e.preventDefault();
  if (!canEdit('expenses')) return;
  const id = document.getElementById('expenseId').value;
  const data = {
    desc: document.getElementById('expenseDesc').value.trim(),
    category: document.getElementById('expenseCategory').value,
    amount: parseFloat(document.getElementById('expenseAmount').value),
    date: document.getElementById('expenseDate').value,
  };
  if (id){
    const idx = expenses.findIndex(x => x.id === id);
    if (idx > -1){
      expenses[idx] = { ...expenses[idx], ...data };
      logHistory(`Expense updated — ${data.desc} (${fmtMoney(data.amount)})`, 'neutral');
    }
  } else {
    expenses.unshift({ id: uid(), ...data });
    logHistory(`New expense — ${data.desc} (${fmtMoney(data.amount)})`, 'expense');
  }
  saveJSON(STORAGE_KEYS.EXPENSES, expenses);
  closeModal(expenseModal);
  renderExpenses();
  renderDashboard();
});

function renderExpenses(){
  expensesTableBody.innerHTML = '';
  expensesEmpty.classList.toggle('hidden', expenses.length > 0);
  const canEditExpenses = canEdit('expenses');
  expenses.forEach(x => {
    const tr = document.createElement('tr');
    tr.innerHTML = `
      <td>${escapeHTML(x.desc)}</td>
      <td>${escapeHTML(x.category)}</td>
      <td>${fmtMoney(x.amount)}</td>
      <td>${fmtDate(x.date)}</td>
      <td>
        ${canEditExpenses ? `<div class="row-actions">
          <button class="icon-btn" data-edit="${x.id}">Edit</button>
          <button class="icon-btn danger" data-del="${x.id}">Delete</button>
        </div>` : ''}
      </td>`;
    expensesTableBody.appendChild(tr);
  });

  expensesTableBody.querySelectorAll('[data-edit]').forEach(btn => {
    btn.addEventListener('click', () => {
      const x = expenses.find(e => e.id === btn.dataset.edit);
      if (x) openExpenseModal(x);
    });
  });
  expensesTableBody.querySelectorAll('[data-del]').forEach(btn => {
    btn.addEventListener('click', () => {
      const x = expenses.find(e => e.id === btn.dataset.del);
      confirmAction(
        'Delete this expense?',
        `This will permanently remove "${x ? x.desc : ''}".`,
        () => {
          expenses = expenses.filter(e => e.id !== btn.dataset.del);
          saveJSON(STORAGE_KEYS.EXPENSES, expenses);
          logHistory(`Expense deleted — ${x ? x.desc : ''}`, 'income');
          renderExpenses();
          renderDashboard();
        }
      );
    });
  });
}

/* ---------------------------------------------------------------
   USERS  (Admin-only management)
   --------------------------------------------------------------- */
const usersTableBody = document.getElementById('usersTableBody');
const usersEmpty = document.getElementById('usersEmpty');
const usersRestricted = document.getElementById('usersRestricted');
const usersTableWrap = document.getElementById('usersTableWrap');
const userCountEl = document.getElementById('userCount');
const userModal = document.getElementById('userModal');
const userForm = document.getElementById('userForm');
const userModalTitle = document.getElementById('userModalTitle');
const userPasswordHint = document.getElementById('userPasswordHint');
const userFormMsg = document.getElementById('userFormMsg');

document.getElementById('addUserBtn').addEventListener('click', () => {
  if (!isAdmin()) return;
  openUserModal();
});
document.getElementById('userCancelBtn').addEventListener('click', () => closeModal(userModal));

function roleTagClass(role){
  const def = getRoleDef(role);
  if (def.isOwner) return 'tag-role-admin';
  if (def.fullAccess) return 'tag-role-manager';
  return 'tag-role-staff';
}

const userPermissionsWrap = document.getElementById('userPermissionsWrap');
const userRoleSelect = document.getElementById('userRole');
userRoleSelect.addEventListener('change', () => {
  userPermissionsWrap.classList.toggle('hidden', getRoleDef(userRoleSelect.value).fullAccess);
});

function openUserModal(user){
  userForm.reset();
  userFormMsg.textContent = '';
  document.getElementById('userId').value = user ? user.id : '';
  userModalTitle.textContent = user ? 'Edit User' : 'New User';
  document.getElementById('userPassword').required = !user;
  document.getElementById('userPasswordLabel').textContent = user ? 'New Password' : 'Password';
  userPasswordHint.classList.toggle('hidden', !user);

  // Role list always comes from Settings → Manage Lists, so a newly added
  // or renamed role shows up here immediately, no code changes needed.
  populateSelect(userRoleSelect, (settings.roles || []).map(r => r.name));

  document.querySelectorAll('.userPerm').forEach(cb => { cb.checked = false; });

  const userAvatarData = document.getElementById('userAvatarData');
  const userAvatarPreview = document.getElementById('userAvatarPreview');
  userAvatarData.value = (user && user.avatar) || '';
  userAvatarPreview.innerHTML = userAvatarData.value
    ? `<img src="${userAvatarData.value}" alt="">`
    : escapeHTML(initials(user ? user.name : ''));

  if (user){
    document.getElementById('userName').value = user.name;
    document.getElementById('userUsername').value = user.username;
    userRoleSelect.value = user.role;
    document.getElementById('userStatus').value = user.status;
    const perms = Array.isArray(user.permissions) ? user.permissions : [];
    document.querySelectorAll('.userPerm').forEach(cb => { cb.checked = perms.includes(cb.value); });
  } else {
    // Default to the least-privileged (non full-access) role if one exists,
    // otherwise just the first role in the list.
    const nonFullAccess = (settings.roles || []).find(r => !r.fullAccess);
    userRoleSelect.value = nonFullAccess ? nonFullAccess.name : (settings.roles[0] && settings.roles[0].name) || '';
    document.getElementById('userStatus').value = 'Active';
  }
  userPermissionsWrap.classList.toggle('hidden', getRoleDef(userRoleSelect.value).fullAccess);
  userModal.classList.remove('hidden');
}

document.getElementById('userAvatarInput').addEventListener('change', async (e) => {
  const file = e.target.files[0];
  e.target.value = ''; // allow picking the same file again later
  if (!file) return;
  try{
    const dataUrl = await fileToResizedDataURL(file, 240);
    document.getElementById('userAvatarData').value = dataUrl;
    document.getElementById('userAvatarPreview').innerHTML = `<img src="${dataUrl}" alt="">`;
  }catch(err){
    alert(err.message);
  }
});
document.getElementById('userAvatarRemoveBtn').addEventListener('click', () => {
  document.getElementById('userAvatarData').value = '';
  const name = document.getElementById('userName').value;
  document.getElementById('userAvatarPreview').innerHTML = escapeHTML(initials(name));
});

userForm.addEventListener('submit', (e) => {
  e.preventDefault();
  if (!isAdmin()) return;

  const id = document.getElementById('userId').value;
  const name = document.getElementById('userName').value.trim();
  const username = document.getElementById('userUsername').value.trim();
  const password = document.getElementById('userPassword').value;
  const role = document.getElementById('userRole').value;
  const status = document.getElementById('userStatus').value;
  const permissions = [...document.querySelectorAll('.userPerm:checked')].map(cb => cb.value);
  const avatar = document.getElementById('userAvatarData').value || null;

  const dupe = users.find(u => u.username.toLowerCase() === username.toLowerCase() && u.id !== id);
  if (dupe){
    userFormMsg.textContent = 'That username is already taken.';
    userFormMsg.className = 'form-msg err';
    return;
  }

  if (id){
    const idx = users.findIndex(u => u.id === id);
    if (idx === -1) return;
    const target = users[idx];
    const isSelf = target.id === currentUserId;

    // Don't let the last remaining Owner-flagged user lock everyone out
    const wasOwner = getRoleDef(target.role).isOwner;
    const willBeOwner = getRoleDef(role).isOwner;
    const otherOwners = users.filter(u => getRoleDef(u.role).isOwner && u.id !== id);
    if (wasOwner && otherOwners.length === 0){
      if (!willBeOwner){
        userFormMsg.textContent = 'You can\'t change the role of the last remaining Owner-level user.';
        userFormMsg.className = 'form-msg err';
        return;
      }
      if (status !== 'Active'){
        userFormMsg.textContent = 'You can\'t deactivate the last remaining Owner-level user.';
        userFormMsg.className = 'form-msg err';
        return;
      }
    }
    if (isSelf && wasOwner && !willBeOwner){
      userFormMsg.textContent = 'You can\'t remove your own Owner-level role.';
      userFormMsg.className = 'form-msg err';
      return;
    }

    users[idx] = {
      ...target,
      name, username, role, status, permissions, avatar,
      password: password ? password : target.password,
    };
    logHistory(`User updated — ${name} (${role})`, 'neutral');
    if (password){
      const me = getCurrentUser();
      logHistory(`Password changed for ${name} by ${me ? me.name : 'Admin'}`, 'neutral');
    }
  } else {
    users.unshift({
      id: uid(), name, username, password, role, status, permissions, avatar,
      lastLogin: null, createdAt: new Date().toISOString(),
    });
    logHistory(`New user added — ${name} (${role})`, 'neutral');
  }

  saveJSON(STORAGE_KEYS.USERS, users);
  closeModal(userModal);
  renderUsers();
  applyRoleUI();
  renderAccountSettings();
});

function renderUsers(){
  const admin = isAdmin();
  renderPasswordRequests();
  renderPhotoRequests();
  usersRestricted.classList.toggle('hidden', admin);
  usersTableWrap.classList.toggle('hidden', !admin);
  if (!admin) return;

  usersTableBody.innerHTML = '';
  usersEmpty.classList.toggle('hidden', users.length > 0);
  userCountEl.textContent = `${users.length} user${users.length === 1 ? '' : 's'}`;

  const moduleLabels = { items: 'Items', orders: 'Orders', expenses: 'Expenses', invoices: 'Sales' };

  users.forEach(u => {
    const isSelf = u.id === currentUserId;
    const tr = document.createElement('tr');
    let accessHTML;
    if (getRoleDef(u.role).fullAccess){
      accessHTML = `<span class="access-badge all">All</span>`;
    } else {
      const perms = Array.isArray(u.permissions) ? u.permissions : [];
      accessHTML = perms.length
        ? `<div class="access-badges">${perms.map(p => `<span class="access-badge">${moduleLabels[p] || p}</span>`).join('')}</div>`
        : `<span class="access-badge none">None</span>`;
    }
    tr.innerHTML = `
      <td><div class="avatar-cell">${avatarHTML(u)}<span>${escapeHTML(u.name)}${isSelf ? ' <span class="you-badge">(you)</span>' : ''}</span></div></td>
      <td>${escapeHTML(u.username)}</td>
      <td><span class="tag ${roleTagClass(u.role)}">${u.role}</span></td>
      <td>${accessHTML}</td>
      <td><span class="status-pill status-${u.status}">${u.status}</span></td>
      <td>${u.lastLogin ? fmtDateTime(u.lastLogin) : 'Never'}</td>
      <td>
        <div class="row-actions">
          <button class="icon-btn" data-edit="${u.id}">Edit</button>
          <button class="icon-btn danger" data-del="${u.id}">Delete</button>
        </div>
      </td>`;
    usersTableBody.appendChild(tr);
  });

  usersTableBody.querySelectorAll('[data-edit]').forEach(btn => {
    btn.addEventListener('click', () => {
      const u = users.find(x => x.id === btn.dataset.edit);
      if (u) openUserModal(u);
    });
  });
  usersTableBody.querySelectorAll('[data-del]').forEach(btn => {
    btn.addEventListener('click', () => {
      const u = users.find(x => x.id === btn.dataset.del);
      if (!u) return;
      if (u.id === currentUserId){
        alert("You can't delete your own account while logged in.");
        return;
      }
      if (getRoleDef(u.role).isOwner && users.filter(x => getRoleDef(x.role).isOwner).length <= 1){
        alert("You can't delete the last remaining Owner-level user.");
        return;
      }
      confirmAction(
        'Delete this user?',
        `This will permanently remove "${u.name}" and revoke their access.`,
        () => {
          users = users.filter(x => x.id !== btn.dataset.del);
          saveJSON(STORAGE_KEYS.USERS, users);
          logHistory(`User deleted — ${u.name}`, 'neutral');
          renderUsers();
        }
      );
    });
  });
}

/* ---------------------------------------------------------------
   TASKS  (Full-Access roles assign — everyone sees the board)
   --------------------------------------------------------------- */
const tasksTableBody = document.getElementById('tasksTableBody');
const tasksEmpty = document.getElementById('tasksEmpty');
const taskCountEl = document.getElementById('taskCount');
const taskSearchInput = document.getElementById('taskSearch');
const taskModal = document.getElementById('taskModal');
const taskForm = document.getElementById('taskForm');
const taskModalTitle = document.getElementById('taskModalTitle');
const taskFormMsg = document.getElementById('taskFormMsg');

document.getElementById('addTaskBtn').addEventListener('click', () => {
  if (!canManageTasks()){
    alert('Only Full-Access roles can create new tasks.');
    return;
  }
  openTaskModal();
});
document.getElementById('taskCancelBtn').addEventListener('click', () => closeModal(taskModal));

taskSearchInput.addEventListener('input', () => {
  taskSearchTerm = taskSearchInput.value.trim().toLowerCase();
  renderTasks();
});

function priorityTagClass(p){
  return p === 'High' ? 'tag-expense' : p === 'Low' ? 'tag-income' : 'tag-neutral';
}

function syncTaskAssigneeOptions(){
  const sel = document.getElementById('taskAssignee');
  const activeUsers = users.filter(u => u.status === 'Active');
  sel.innerHTML = activeUsers.map(u => `<option value="${u.id}">${escapeHTML(u.name)} — ${escapeHTML(u.role)}</option>`).join('');
}

function openTaskModal(task){
  taskForm.reset();
  taskFormMsg.textContent = '';
  document.getElementById('taskId').value = task ? task.id : '';
  taskModalTitle.textContent = task ? 'Edit Task' : 'New Task';
  syncTaskAssigneeOptions();
  populateSelect(document.getElementById('taskPriority'), settings.taskPriorities);
  populateSelect(document.getElementById('taskStatus'), settings.taskStatuses);

  const manage = canManageTasks();
  ['taskTitle','taskDescription','taskAssignee','taskPriority','taskDueDate'].forEach(id => {
    document.getElementById(id).disabled = !!task && !manage;
  });

  if (task){
    document.getElementById('taskTitle').value = task.title;
    document.getElementById('taskDescription').value = task.description || '';
    document.getElementById('taskAssignee').value = task.assignedTo || '';
    document.getElementById('taskPriority').value = task.priority;
    document.getElementById('taskDueDate').value = task.dueDate || '';
    document.getElementById('taskStatus').value = task.status;
  } else {
    document.getElementById('taskStatus').value = settings.taskStatuses[0] || 'To Do';
  }
  taskModal.classList.remove('hidden');
}

taskForm.addEventListener('submit', (e) => {
  e.preventDefault();

  const id = document.getElementById('taskId').value;
  const title = document.getElementById('taskTitle').value.trim();
  const description = document.getElementById('taskDescription').value.trim();
  const assignedTo = document.getElementById('taskAssignee').value;
  const priority = document.getElementById('taskPriority').value;
  const dueDate = document.getElementById('taskDueDate').value || null;
  const status = document.getElementById('taskStatus').value;
  const assignee = users.find(u => u.id === assignedTo);
  const me = getCurrentUser();
  const manage = canManageTasks();

  if (!id && !manage){
    taskFormMsg.textContent = 'Only Full-Access roles can create tasks.';
    taskFormMsg.className = 'form-msg err';
    return;
  }

  if (id){
    const idx = tasks.findIndex(t => t.id === id);
    if (idx === -1) return;
    const existing = tasks[idx];
    const isMine = existing.assignedTo === currentUserId;
    if (!manage && !isMine){
      taskFormMsg.textContent = 'You can only update the status of tasks assigned to you.';
      taskFormMsg.className = 'form-msg err';
      return;
    }
    tasks[idx] = manage
      ? { ...existing, title, description, assignedTo: assignedTo || null, assignedToName: assignee ? assignee.name : null, priority, dueDate, status }
      : { ...existing, status };
    logHistory(`Task updated — ${existing.title} (${me ? me.name : 'Unknown'})`, 'neutral');
  } else {
    tasks.unshift({
      id: uid(), title, description,
      assignedTo: assignedTo || null,
      assignedToName: assignee ? assignee.name : null,
      priority, dueDate, status,
      createdBy: currentUserId,
      createdByName: me ? me.name : null,
      createdAt: new Date().toISOString(),
    });
    logHistory(`New task assigned — ${title} → ${assignee ? assignee.name : 'Unassigned'}`, 'neutral');
  }

  saveJSON(STORAGE_KEYS.TASKS, tasks);
  closeModal(taskModal);
  renderTasks();
});

function renderTasks(){
  const term = taskSearchTerm;
  const filtered = term
    ? tasks.filter(t => t.title.toLowerCase().includes(term) || (t.assignedToName || '').toLowerCase().includes(term))
    : tasks;

  tasksTableBody.innerHTML = '';
  tasksEmpty.classList.toggle('hidden', filtered.length > 0);
  tasksEmpty.textContent = term && tasks.length > 0
    ? 'No tasks match your search.'
    : 'No tasks yet. Click "New Task" to assign your first one.';
  taskCountEl.textContent = term
    ? `${filtered.length} of ${tasks.length} tasks`
    : `${tasks.length} task${tasks.length === 1 ? '' : 's'}`;

  const me = getCurrentUser();
  const manage = canManageTasks();
  const todayStr = new Date().toISOString().slice(0, 10);

  filtered.forEach(t => {
    const overdue = t.dueDate && t.status !== 'Done' && t.dueDate < todayStr;
    const isMine = !!me && t.assignedTo === me.id;
    const canOpen = manage || isMine;
    const statusClass = t.status.replace(/\s/g, '');
    const tr = document.createElement('tr');
    tr.innerHTML = `
      <td>${escapeHTML(t.title)}</td>
      <td>${escapeHTML(t.assignedToName || 'Unassigned')}${isMine ? ' <span class="you-badge">(you)</span>' : ''}</td>
      <td><span class="tag ${priorityTagClass(t.priority)}">${t.priority}</span></td>
      <td class="${overdue ? 'low-stock' : ''}">${t.dueDate ? fmtDate(t.dueDate) : '—'}${overdue ? ' ⚠' : ''}</td>
      <td><span class="status-pill status-${statusClass}">${t.status}</span></td>
      <td>
        <div class="row-actions">
          ${canOpen ? `<button class="icon-btn" data-edit="${t.id}">${manage ? 'Edit' : 'Update'}</button>` : ''}
          ${manage ? `<button class="icon-btn danger" data-del="${t.id}">Delete</button>` : ''}
        </div>
      </td>`;
    tasksTableBody.appendChild(tr);
  });

  tasksTableBody.querySelectorAll('[data-edit]').forEach(btn => {
    btn.addEventListener('click', () => {
      const t = tasks.find(x => x.id === btn.dataset.edit);
      if (t) openTaskModal(t);
    });
  });
  tasksTableBody.querySelectorAll('[data-del]').forEach(btn => {
    btn.addEventListener('click', () => {
      const t = tasks.find(x => x.id === btn.dataset.del);
      if (!t) return;
      confirmAction(
        'Delete this task?',
        `This will permanently remove "${t.title}".`,
        () => {
          tasks = tasks.filter(x => x.id !== btn.dataset.del);
          saveJSON(STORAGE_KEYS.TASKS, tasks);
          const actor = getCurrentUser();
          logHistory(`Task deleted — ${t.title} (${actor ? actor.name : 'Unknown'})`, 'neutral');
          renderTasks();
        }
      );
    });
  });
}

/* ---------------------------------------------------------------
   REPORTS
   --------------------------------------------------------------- */
const reportYearSelect = document.getElementById('reportYearSelect');
const reportMonthlyBody = document.getElementById('reportMonthlyBody');
const reportMonthlyFoot = document.getElementById('reportMonthlyFoot');
const reportCategoryBody = document.getElementById('reportCategoryBody');
const reportCategoryEmpty = document.getElementById('reportCategoryEmpty');
const reportCategoryTable = document.getElementById('reportCategoryTable');

let reportYear = null;

function getAvailableYears(){
  const years = new Set();
  orders.forEach(o => { const y = new Date(o.date).getFullYear(); if (!isNaN(y)) years.add(y); });
  expenses.forEach(x => { const y = new Date(x.date).getFullYear(); if (!isNaN(y)) years.add(y); });
  stockMoves.forEach(m => { const y = new Date(m.date).getFullYear(); if (!isNaN(y)) years.add(y); });
  years.add(new Date().getFullYear());
  return [...years].sort((a, b) => b - a);
}

function computeYearlyMonthlyReport(year){
  const months = [];
  for (let m = 0; m < 12; m++){
    months.push({
      monthIndex: m,
      label: new Date(year, m, 1).toLocaleDateString('en-GB', { month: 'long' }),
      ordersCount: 0,
      sales: 0,
      income: 0,
      expenses: 0,
      stockIn: 0,
      stockOut: 0,
    });
  }
  orders.forEach(o => {
    const d = new Date(o.date);
    if (d.getFullYear() !== year) return;
    const bucket = months[d.getMonth()];
    bucket.ordersCount++;
    bucket.sales += Number(o.amount) || 0;
    if (o.status === 'Delivered') bucket.income += Number(o.amount) || 0;
  });
  expenses.forEach(x => {
    const d = new Date(x.date);
    if (d.getFullYear() !== year) return;
    months[d.getMonth()].expenses += Number(x.amount) || 0;
  });
  stockMoves.forEach(sm => {
    const d = new Date(sm.date);
    if (d.getFullYear() !== year) return;
    const bucket = months[d.getMonth()];
    if (sm.type === 'in') bucket.stockIn += Number(sm.qty) || 0;
    else bucket.stockOut += Number(sm.qty) || 0;
  });
  months.forEach(m => { m.profit = m.income - m.expenses; });
  return months;
}

function computeExpenseCategoryBreakdown(year){
  const totals = {};
  let grandTotal = 0;
  expenses.forEach(x => {
    const d = new Date(x.date);
    if (d.getFullYear() !== year) return;
    const amt = Number(x.amount) || 0;
    totals[x.category] = (totals[x.category] || 0) + amt;
    grandTotal += amt;
  });
  const rows = Object.entries(totals)
    .map(([category, amount]) => ({ category, amount, pct: grandTotal ? (amount / grandTotal * 100) : 0 }))
    .sort((a, b) => b.amount - a.amount);
  return { grandTotal, rows };
}

function populateReportYearSelect(){
  const years = getAvailableYears();
  const prevSelection = reportYear;
  reportYearSelect.innerHTML = years.map(y => `<option value="${y}">${y}</option>`).join('');
  reportYear = years.includes(prevSelection) ? prevSelection : years[0];
  reportYearSelect.value = reportYear;
}

reportYearSelect.addEventListener('change', () => {
  reportYear = parseInt(reportYearSelect.value, 10);
  renderReportBody();
});

function renderReports(){
  populateReportYearSelect();
  renderReportBody();
}

function renderReportBody(){
  const months = computeYearlyMonthlyReport(reportYear);
  const totals = months.reduce((acc, m) => {
    acc.orders += m.ordersCount;
    acc.sales += m.sales;
    acc.income += m.income;
    acc.expenses += m.expenses;
    acc.stockIn += m.stockIn;
    acc.stockOut += m.stockOut;
    return acc;
  }, { orders: 0, sales: 0, income: 0, expenses: 0, stockIn: 0, stockOut: 0 });
  const netProfit = totals.income - totals.expenses;

  document.getElementById('reportStatIncome').textContent = fmtMoney(totals.income);
  document.getElementById('reportStatExpense').textContent = fmtMoney(totals.expenses);
  const netEl = document.getElementById('reportStatNet');
  netEl.textContent = fmtMoney(netProfit);
  netEl.style.color = netProfit >= 0 ? 'var(--income)' : 'var(--expense)';
  document.getElementById('reportStatNetFoot').textContent = netProfit >= 0 ? 'Profit' : 'Loss';
  document.getElementById('reportStatOrders').textContent = totals.orders;
  document.getElementById('reportStatSales').textContent = fmtMoney(totals.sales);
  document.getElementById('reportStatIncomeFoot').textContent = `From delivered orders — ${reportYear}`;
  document.getElementById('reportTableSub').textContent = `Every month of ${reportYear}`;

  reportMonthlyBody.innerHTML = '';
  months.forEach(m => {
    const tr = document.createElement('tr');
    tr.innerHTML = `
      <td>${m.label}</td>
      <td>${m.ordersCount}</td>
      <td>${fmtMoney(m.income)}</td>
      <td>${fmtMoney(m.expenses)}</td>
      <td style="color:${m.profit >= 0 ? 'var(--income)' : 'var(--expense)'}">${fmtMoney(m.profit)}</td>
      <td><span style="color:var(--income)">+${m.stockIn}</span> / <span style="color:var(--expense)">-${m.stockOut}</span></td>`;
    reportMonthlyBody.appendChild(tr);
  });
  reportMonthlyFoot.innerHTML = `
    <tr>
      <td>Total</td>
      <td>${totals.orders}</td>
      <td>${fmtMoney(totals.income)}</td>
      <td>${fmtMoney(totals.expenses)}</td>
      <td style="color:${netProfit >= 0 ? 'var(--income)' : 'var(--expense)'}">${fmtMoney(netProfit)}</td>
      <td><span style="color:var(--income)">+${totals.stockIn}</span> / <span style="color:var(--expense)">-${totals.stockOut}</span></td>
    </tr>`;

  const breakdown = computeExpenseCategoryBreakdown(reportYear);
  reportCategoryBody.innerHTML = '';
  reportCategoryTable.classList.toggle('hidden', breakdown.rows.length === 0);
  reportCategoryEmpty.classList.toggle('hidden', breakdown.rows.length > 0);
  breakdown.rows.forEach(r => {
    const tr = document.createElement('tr');
    tr.innerHTML = `
      <td>${escapeHTML(r.category)}</td>
      <td>${fmtMoney(r.amount)}</td>
      <td>
        <div class="category-bar-wrap">
          <div class="category-bar-track"><div class="category-bar-fill" style="width:${r.pct.toFixed(1)}%"></div></div>
          <span class="category-pct">${r.pct.toFixed(1)}%</span>
        </div>
      </td>`;
    reportCategoryBody.appendChild(tr);
  });
}

document.getElementById('exportReportBtn').addEventListener('click', () => {
  if (typeof XLSX === 'undefined'){
    alert('The Excel export library failed to load. Please check your internet connection and try again.');
    return;
  }
  const year = reportYear;
  const months = computeYearlyMonthlyReport(year);
  const totals = months.reduce((acc, m) => {
    acc.orders += m.ordersCount;
    acc.sales += m.sales;
    acc.income += m.income;
    acc.expenses += m.expenses;
    acc.stockIn += m.stockIn;
    acc.stockOut += m.stockOut;
    return acc;
  }, { orders: 0, sales: 0, income: 0, expenses: 0, stockIn: 0, stockOut: 0 });
  const netProfit = totals.income - totals.expenses;

  const wb = XLSX.utils.book_new();

  // Sheet 1 — Monthly Summary
  const summaryRows = [
    ['Month', 'Orders', 'Income (Rs)', 'Expenses (Rs)', 'Profit / Loss (Rs)', 'Stock In (units)', 'Stock Out (units)'],
    ...months.map(m => [m.label, m.ordersCount, m.income, m.expenses, m.profit, m.stockIn, m.stockOut]),
    ['Total', totals.orders, totals.income, totals.expenses, netProfit, totals.stockIn, totals.stockOut],
  ];
  const summarySheet = XLSX.utils.aoa_to_sheet(summaryRows);
  summarySheet['!cols'] = [{ wch: 12 }, { wch: 9 }, { wch: 14 }, { wch: 14 }, { wch: 16 }, { wch: 15 }, { wch: 15 }];
  XLSX.utils.book_append_sheet(wb, summarySheet, 'Monthly Summary');

  // Sheet 2 — Expense Categories
  const breakdown = computeExpenseCategoryBreakdown(year);
  const catRows = [
    ['Category', 'Amount (Rs)', 'Share of Total (%)'],
    ...breakdown.rows.map(r => [r.category, r.amount, Number(r.pct.toFixed(1))]),
    ['Total', breakdown.grandTotal, 100],
  ];
  const catSheet = XLSX.utils.aoa_to_sheet(catRows);
  catSheet['!cols'] = [{ wch: 20 }, { wch: 14 }, { wch: 16 }];
  XLSX.utils.book_append_sheet(wb, catSheet, 'Expense Categories');

  // Sheet 3 — Orders detail
  const yearOrders = orders
    .filter(o => new Date(o.date).getFullYear() === year)
    .sort((a, b) => new Date(a.date) - new Date(b.date));
  const orderRows = [
    ['Order ID', 'Date', 'Customer', 'Contact', 'Email', 'Item / Service', 'Amount (Rs)', 'Status'],
    ...yearOrders.map(o => ['#' + o.id.slice(-6).toUpperCase(), fmtDate(o.date), o.customer, o.contact || '', o.email || '', o.item, Number(o.amount) || 0, o.status]),
  ];
  const orderSheet = XLSX.utils.aoa_to_sheet(orderRows);
  orderSheet['!cols'] = [{ wch: 12 }, { wch: 12 }, { wch: 20 }, { wch: 16 }, { wch: 24 }, { wch: 22 }, { wch: 14 }, { wch: 12 }];
  XLSX.utils.book_append_sheet(wb, orderSheet, 'Orders');

  // Sheet 4 — Expenses detail
  const yearExpenses = expenses
    .filter(x => new Date(x.date).getFullYear() === year)
    .sort((a, b) => new Date(a.date) - new Date(b.date));
  const expenseRows = [
    ['Description', 'Date', 'Category', 'Amount (Rs)'],
    ...yearExpenses.map(x => [x.desc, fmtDate(x.date), x.category, Number(x.amount) || 0]),
  ];
  const expenseSheet = XLSX.utils.aoa_to_sheet(expenseRows);
  expenseSheet['!cols'] = [{ wch: 26 }, { wch: 12 }, { wch: 18 }, { wch: 14 }];
  XLSX.utils.book_append_sheet(wb, expenseSheet, 'Expenses');

  // Sheet 5 — Stock Movements detail
  const yearStockMoves = stockMoves
    .filter(m => new Date(m.date).getFullYear() === year)
    .sort((a, b) => new Date(a.date) - new Date(b.date));
  const stockRows = [
    ['Date', 'Item', 'Movement', 'Qty', 'Remaining After', 'Note'],
    ...yearStockMoves.map(m => [fmtDate(m.date), m.itemName, m.type === 'in' ? 'Stock In' : 'Stock Out', m.qty, m.remainingAfter, m.note || '']),
  ];
  const stockSheet = XLSX.utils.aoa_to_sheet(stockRows);
  stockSheet['!cols'] = [{ wch: 12 }, { wch: 22 }, { wch: 12 }, { wch: 8 }, { wch: 15 }, { wch: 28 }];
  XLSX.utils.book_append_sheet(wb, stockSheet, 'Stock Movements');

  XLSX.writeFile(wb, `elite-digital-hub-report-${year}.xlsx`);
  logHistory(`Excel report exported — ${year}`, 'neutral');
});

/* ---------------------------------------------------------------
   REPORTS — Month & Custom Date Range Excel Downloads
   --------------------------------------------------------------- */
function categoryBreakdownFor(expenseList){
  const totals = {};
  let grandTotal = 0;
  expenseList.forEach(x => {
    const amt = Number(x.amount) || 0;
    totals[x.category] = (totals[x.category] || 0) + amt;
    grandTotal += amt;
  });
  const rows = Object.entries(totals)
    .map(([category, amount]) => ({ category, amount, pct: grandTotal ? (amount / grandTotal * 100) : 0 }))
    .sort((a, b) => b.amount - a.amount);
  return { grandTotal, rows };
}

// Builds one row per calendar date between fromDate and toDate (inclusive),
// even for dates with zero activity — so the sheet always covers the full
// month/range, date by date, instead of only the days something happened.
function buildDailyBreakdownRows(fromDate, toDate, rangeOrders, rangeExpenses, rangeStockMoves){
  const dayKey = (d) => {
    const dt = new Date(d);
    return `${dt.getFullYear()}-${String(dt.getMonth()+1).padStart(2,'0')}-${String(dt.getDate()).padStart(2,'0')}`;
  };

  const byDay = {};
  const ensureDay = (key) => {
    if (!byDay[key]){
      byDay[key] = { orders: 0, sales: 0, income: 0, expenses: 0, stockIn: 0, stockOut: 0 };
    }
    return byDay[key];
  };

  rangeOrders.forEach(o => {
    const day = ensureDay(dayKey(o.date));
    day.orders += 1;
    day.sales += Number(o.amount) || 0;
    if (o.status === 'Delivered') day.income += Number(o.amount) || 0;
  });
  rangeExpenses.forEach(x => {
    const day = ensureDay(dayKey(x.date));
    day.expenses += Number(x.amount) || 0;
  });
  rangeStockMoves.forEach(m => {
    const day = ensureDay(dayKey(m.date));
    if (m.type === 'in') day.stockIn += Number(m.qty) || 0;
    else day.stockOut += Number(m.qty) || 0;
  });

  const rows = [];
  const cursor = new Date(fromDate + 'T00:00:00');
  const end = new Date(toDate + 'T00:00:00');
  while (cursor <= end){
    const key = dayKey(cursor);
    const d = byDay[key] || { orders: 0, sales: 0, income: 0, expenses: 0, stockIn: 0, stockOut: 0 };
    rows.push([
      fmtDate(key),
      d.orders,
      d.sales,
      d.income,
      d.expenses,
      d.income - d.expenses,
      d.stockIn,
      d.stockOut,
    ]);
    cursor.setDate(cursor.getDate() + 1);
  }
  return rows;
}


function downloadRangeExcel(fromDate, toDate, label, filenameSuffix){
  if (typeof XLSX === 'undefined'){
    alert('The Excel export library failed to load. Please check your internet connection and try again.');
    return;
  }
  const from = new Date(fromDate + 'T00:00:00');
  const to = new Date(toDate + 'T23:59:59');

  const rangeOrders = orders
    .filter(o => { const d = new Date(o.date); return d >= from && d <= to; })
    .sort((a, b) => new Date(a.date) - new Date(b.date));
  const rangeExpenses = expenses
    .filter(x => { const d = new Date(x.date); return d >= from && d <= to; })
    .sort((a, b) => new Date(a.date) - new Date(b.date));
  const rangeStockMoves = stockMoves
    .filter(m => { const d = new Date(m.date); return d >= from && d <= to; })
    .sort((a, b) => new Date(a.date) - new Date(b.date));

  const totalOrders = rangeOrders.length;
  const totalSales = rangeOrders.reduce((s, o) => s + (Number(o.amount) || 0), 0);
  const totalIncome = rangeOrders.filter(o => o.status === 'Delivered').reduce((s, o) => s + (Number(o.amount) || 0), 0);
  const totalExpenses = rangeExpenses.reduce((s, x) => s + (Number(x.amount) || 0), 0);
  const netProfit = totalIncome - totalExpenses;
  const totalStockIn = rangeStockMoves.filter(m => m.type === 'in').reduce((s, m) => s + (Number(m.qty) || 0), 0);
  const totalStockOut = rangeStockMoves.filter(m => m.type === 'out').reduce((s, m) => s + (Number(m.qty) || 0), 0);

  const wb = XLSX.utils.book_new();

  // Sheet 1 — Summary
  const summaryRows = [
    ['Report Period', label],
    [],
    ['Metric', 'Value'],
    ['Total Orders', totalOrders],
    ['Total Sales Value (Rs)', totalSales],
    ['Total Income — Delivered Orders (Rs)', totalIncome],
    ['Total Expenses (Rs)', totalExpenses],
    ['Net Profit / Loss (Rs)', netProfit],
    ['Total Stock In (units)', totalStockIn],
    ['Total Stock Out (units)', totalStockOut],
  ];
  const summarySheet = XLSX.utils.aoa_to_sheet(summaryRows);
  summarySheet['!cols'] = [{ wch: 32 }, { wch: 18 }];
  XLSX.utils.book_append_sheet(wb, summarySheet, 'Summary');

  // Sheet 2 — Daily Breakdown (date-wise, every date in the range/month —
  // this is the sheet that guarantees the report covers the WHOLE month,
  // day by day, even for dates with no activity)
  const dailyRows = buildDailyBreakdownRows(fromDate, toDate, rangeOrders, rangeExpenses, rangeStockMoves);
  const dailySheet = XLSX.utils.aoa_to_sheet([
    ['Date', 'Orders', 'Sales Value (Rs)', 'Income — Delivered (Rs)', 'Expenses (Rs)', 'Net (Rs)', 'Stock In', 'Stock Out'],
    ...dailyRows,
  ]);
  dailySheet['!cols'] = [{ wch: 14 }, { wch: 10 }, { wch: 16 }, { wch: 20 }, { wch: 14 }, { wch: 14 }, { wch: 10 }, { wch: 10 }];
  XLSX.utils.book_append_sheet(wb, dailySheet, 'Daily Breakdown');

  // Sheet 3 — Orders detail
  const orderRows = [
    ['Order ID', 'Date', 'Customer', 'Contact', 'Email', 'Item / Service', 'Amount (Rs)', 'Status'],
    ...rangeOrders.map(o => ['#' + o.id.slice(-6).toUpperCase(), fmtDate(o.date), o.customer, o.contact || '', o.email || '', o.item, Number(o.amount) || 0, o.status]),
  ];
  const orderSheet = XLSX.utils.aoa_to_sheet(orderRows);
  orderSheet['!cols'] = [{ wch: 12 }, { wch: 12 }, { wch: 20 }, { wch: 16 }, { wch: 24 }, { wch: 22 }, { wch: 14 }, { wch: 12 }];
  XLSX.utils.book_append_sheet(wb, orderSheet, 'Orders');

  // Sheet 4 — Expenses detail
  const expenseRows = [
    ['Description', 'Date', 'Category', 'Amount (Rs)'],
    ...rangeExpenses.map(x => [x.desc, fmtDate(x.date), x.category, Number(x.amount) || 0]),
  ];
  const expenseSheet = XLSX.utils.aoa_to_sheet(expenseRows);
  expenseSheet['!cols'] = [{ wch: 26 }, { wch: 12 }, { wch: 18 }, { wch: 14 }];
  XLSX.utils.book_append_sheet(wb, expenseSheet, 'Expenses');

  // Sheet 5 — Stock Movements detail
  const stockRows = [
    ['Date', 'Item', 'Movement', 'Qty', 'Remaining After', 'Note'],
    ...rangeStockMoves.map(m => [fmtDate(m.date), m.itemName, m.type === 'in' ? 'Stock In' : 'Stock Out', m.qty, m.remainingAfter, m.note || '']),
  ];
  const stockSheet = XLSX.utils.aoa_to_sheet(stockRows);
  stockSheet['!cols'] = [{ wch: 12 }, { wch: 22 }, { wch: 12 }, { wch: 8 }, { wch: 15 }, { wch: 28 }];
  XLSX.utils.book_append_sheet(wb, stockSheet, 'Stock Movements');

  // Sheet 6 — Expenses by category
  const breakdown = categoryBreakdownFor(rangeExpenses);
  const catRows = [
    ['Category', 'Amount (Rs)', 'Share of Total (%)'],
    ...breakdown.rows.map(r => [r.category, r.amount, Number(r.pct.toFixed(1))]),
    ['Total', breakdown.grandTotal, 100],
  ];
  const catSheet = XLSX.utils.aoa_to_sheet(catRows);
  catSheet['!cols'] = [{ wch: 20 }, { wch: 14 }, { wch: 16 }];
  XLSX.utils.book_append_sheet(wb, catSheet, 'Expense Categories');

  XLSX.writeFile(wb, `elite-digital-hub-report-${filenameSuffix}.xlsx`);
  logHistory(`Excel report exported — ${label}`, 'neutral');
}

const reportDownloadMsg = document.getElementById('reportDownloadMsg');
function showReportDownloadMsg(text, isErr){
  reportDownloadMsg.textContent = text;
  reportDownloadMsg.className = 'form-msg ' + (isErr ? 'err' : 'ok');
}

document.getElementById('exportMonthReportBtn').addEventListener('click', () => {
  const val = document.getElementById('reportMonthPicker').value; // "YYYY-MM"
  if (!val){
    showReportDownloadMsg('Please select a month first.', true);
    return;
  }
  const [y, m] = val.split('-').map(Number);
  const fromDate = `${y}-${String(m).padStart(2,'0')}-01`;
  const lastDay = new Date(y, m, 0).getDate();
  const toDate = `${y}-${String(m).padStart(2,'0')}-${String(lastDay).padStart(2,'0')}`;
  const label = new Date(y, m - 1, 1).toLocaleDateString('en-GB', { month: 'long', year: 'numeric' });
  downloadRangeExcel(fromDate, toDate, label, val);
  showReportDownloadMsg(`Downloaded report for ${label}.`, false);
});

document.getElementById('exportRangeReportBtn').addEventListener('click', () => {
  const fromDate = document.getElementById('reportRangeFrom').value;
  const toDate = document.getElementById('reportRangeTo').value;
  if (!fromDate || !toDate){
    showReportDownloadMsg('Please select both a "from" and "to" date.', true);
    return;
  }
  if (new Date(fromDate) > new Date(toDate)){
    showReportDownloadMsg('"From" date must be before the "to" date.', true);
    return;
  }
  const label = `${fmtDate(fromDate)} – ${fmtDate(toDate)}`;
  downloadRangeExcel(fromDate, toDate, label, `${fromDate}_to_${toDate}`);
  showReportDownloadMsg(`Downloaded report for ${label}.`, false);
});

/* ---------------------------------------------------------------
   HISTORY VIEW
   --------------------------------------------------------------- */
const historyList = document.getElementById('historyList');
const historyEmpty = document.getElementById('historyEmpty');

function renderHistory(){
  historyList.innerHTML = '';
  historyEmpty.classList.toggle('hidden', history.length > 0);
  history.forEach(h => {
    const li = document.createElement('li');
    const tagClass = h.type === 'income' ? 'tag-income'
      : h.type === 'expense' ? 'tag-expense'
      : h.type === 'stock-in' ? 'tag-stock-in'
      : h.type === 'stock-out' ? 'tag-stock-out'
      : h.type === 'stock' ? 'tag-stock'
      : 'tag-neutral';
    li.innerHTML = `<span class="hist-text"><span class="tag ${tagClass}">${h.type}</span>${escapeHTML(h.text)}</span><span class="hist-time">${fmtDateTime(h.time)}</span>`;
    historyList.appendChild(li);
  });
}

