/* ---------------------------------------------------------------
   MANAGE LISTS  (Settings → categories, statuses, priorities, roles)
   Lets the Owner add/remove the values used throughout the app
   without touching any code. Everything here reads/writes `settings`
   and persists via saveSettings().
   --------------------------------------------------------------- */
const SIMPLE_LIST_CONFIG = [
  { key: 'itemCategories', label: 'Item Categories', usedBy: (v) => items.some(i => i.category === v) },
  { key: 'expenseCategories', label: 'Expense Categories', usedBy: (v) => expenses.some(x => x.category === v) },
  { key: 'orderStatuses', label: 'Order / Invoice Statuses', usedBy: (v) => orders.some(o => o.status === v) || invoices.some(inv => inv.status === v) },
  { key: 'taskPriorities', label: 'Task Priorities', usedBy: (v) => tasks.some(t => t.priority === v) },
  { key: 'taskStatuses', label: 'Task Statuses', usedBy: (v) => tasks.some(t => t.status === v) },
];

function renderManageLists(){
  const body = document.getElementById('manageListsBody');
  if (!isAdmin()){ body.innerHTML = ''; return; }

  const simpleGroupsHTML = SIMPLE_LIST_CONFIG.map(cfg => {
    const values = settings[cfg.key] || [];
    const chips = values.map(v => `
      <span class="chip">
        ${escapeHTML(v)}
        <button type="button" class="chip-remove" data-list="${cfg.key}" data-value="${escapeHTML(v)}" title="Remove">&times;</button>
      </span>
    `).join('') || '<span class="empty-inline">No values yet.</span>';
    return `
      <div class="manage-list-group">
        <h4>${cfg.label}</h4>
        <div class="chip-row">${chips}</div>
        <div class="chip-add-row">
          <input type="text" class="chip-add-input" data-list="${cfg.key}" placeholder="Add new ${cfg.label.toLowerCase().replace(/s$/, '')}...">
          <button type="button" class="btn btn-outline btn-sm chip-add-btn" data-list="${cfg.key}">+ Add</button>
        </div>
      </div>`;
  }).join('');

  const roles = settings.roles || [];
  const roleRowsHTML = roles.map(r => `
    <div class="role-row" data-role="${escapeHTML(r.name)}">
      <span class="role-row-name">${escapeHTML(r.name)}</span>
      <label class="checkbox-pill sm"><input type="checkbox" class="roleFullAccess" data-role="${escapeHTML(r.name)}" ${r.fullAccess ? 'checked' : ''}> Full Access</label>
      <label class="checkbox-pill sm"><input type="checkbox" class="roleIsOwner" data-role="${escapeHTML(r.name)}" ${r.isOwner ? 'checked' : ''}> Owner-level</label>
      <button type="button" class="icon-btn danger role-remove" data-role="${escapeHTML(r.name)}">Delete</button>
    </div>
  `).join('');

  body.innerHTML = `
    ${simpleGroupsHTML}
    <div class="manage-list-group">
      <h4>Roles</h4>
      <p class="field-hint-inline">"Full Access" skips per-user module permissions. "Owner-level" additionally unlocks Users, Import Backup, Erase All Data and Manage Lists.</p>
      <div class="role-list">${roleRowsHTML}</div>
      <div class="chip-add-row role-add-row">
        <input type="text" id="newRoleName" placeholder="New role name...">
        <label class="checkbox-pill sm"><input type="checkbox" id="newRoleFullAccess"> Full Access</label>
        <label class="checkbox-pill sm"><input type="checkbox" id="newRoleIsOwner"> Owner-level</label>
        <button type="button" class="btn btn-outline btn-sm" id="addRoleBtn">+ Add Role</button>
      </div>
    </div>
  `;

  // Remove a value from a simple list
  body.querySelectorAll('.chip-remove').forEach(btn => {
    btn.addEventListener('click', () => {
      const listKey = btn.dataset.list;
      const value = btn.dataset.value;
      const cfg = SIMPLE_LIST_CONFIG.find(c => c.key === listKey);
      if ((settings[listKey] || []).length <= 1){
        alert('At least one value must remain in this list.');
        return;
      }
      if (cfg.usedBy(value) && !confirm(`"${value}" is currently used by existing records. Remove it from the list anyway? Existing records will keep showing "${value}" but it won't be selectable for new ones.`)){
        return;
      }
      settings[listKey] = settings[listKey].filter(v => v !== value);
      saveSettings();
      logHistory(`Removed "${value}" from ${cfg.label}`, 'neutral');
      renderManageLists();
    });
  });

  // Add a value to a simple list
  body.querySelectorAll('.chip-add-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      const listKey = btn.dataset.list;
      const cfg = SIMPLE_LIST_CONFIG.find(c => c.key === listKey);
      const input = body.querySelector(`.chip-add-input[data-list="${listKey}"]`);
      const value = input.value.trim();
      if (!value) return;
      settings[listKey] = settings[listKey] || [];
      if (settings[listKey].some(v => v.toLowerCase() === value.toLowerCase())){
        alert('That value already exists.');
        return;
      }
      settings[listKey].push(value);
      saveSettings();
      logHistory(`Added "${value}" to ${cfg.label}`, 'neutral');
      renderManageLists();
    });
  });

  // Toggle a role's Full Access / Owner-level flags
  body.querySelectorAll('.roleFullAccess, .roleIsOwner').forEach(cb => {
    cb.addEventListener('change', () => {
      const roleName = cb.dataset.role;
      const role = settings.roles.find(r => r.name === roleName);
      if (!role) return;
      const willBeOwner = cb.classList.contains('roleIsOwner') ? cb.checked : role.isOwner;
      const otherOwners = settings.roles.filter(r => r.name !== roleName && r.isOwner);
      if (role.isOwner && !willBeOwner && otherOwners.length === 0){
        alert("At least one role must stay Owner-level, otherwise nobody could manage Users or Settings.");
        cb.checked = true;
        return;
      }
      if (cb.classList.contains('roleFullAccess')) role.fullAccess = cb.checked;
      if (cb.classList.contains('roleIsOwner')) role.isOwner = cb.checked;
      saveSettings();
      logHistory(`Updated role "${roleName}" — ${cb.classList.contains('roleFullAccess') ? 'Full Access' : 'Owner-level'}: ${cb.checked ? 'On' : 'Off'}`, 'neutral');
      applyRoleUI(); // in case the current user's own role just changed
    });
  });

  // Delete a role
  body.querySelectorAll('.role-remove').forEach(btn => {
    btn.addEventListener('click', () => {
      const roleName = btn.dataset.role;
      const role = settings.roles.find(r => r.name === roleName);
      if (!role) return;
      if (settings.roles.length <= 1){
        alert('At least one role must remain.');
        return;
      }
      if (users.some(u => u.role === roleName)){
        alert(`Can't delete "${roleName}" — it's still assigned to one or more users. Reassign them first (Users → Edit).`);
        return;
      }
      if (role.isOwner && settings.roles.filter(r => r.isOwner).length <= 1){
        alert("Can't delete the last remaining Owner-level role.");
        return;
      }
      if (!confirm(`Delete the "${roleName}" role?`)) return;
      settings.roles = settings.roles.filter(r => r.name !== roleName);
      saveSettings();
      logHistory(`Deleted role "${roleName}"`, 'expense');
      renderManageLists();
    });
  });

  // Add a new role
  const addRoleBtn = document.getElementById('addRoleBtn');
  if (addRoleBtn){
    addRoleBtn.addEventListener('click', () => {
      const nameInput = document.getElementById('newRoleName');
      const name = nameInput.value.trim();
      if (!name) return;
      if (settings.roles.some(r => r.name.toLowerCase() === name.toLowerCase())){
        alert('That role already exists.');
        return;
      }
      settings.roles.push({
        name,
        fullAccess: document.getElementById('newRoleFullAccess').checked,
        isOwner: document.getElementById('newRoleIsOwner').checked,
      });
      saveSettings();
      logHistory(`Added new role "${name}"`, 'income');
      renderManageLists();
    });
  }
}

changePassForm.addEventListener('submit', (e) => {
  e.preventDefault();
  const me = getCurrentUser();
  if (!me) return;
  if (!isAdmin()) return; // regular users have no editable fields here

  const newUsername = myUsernameInput.value.trim();

  if (!newUsername){
    passChangeMsg.textContent = 'Username cannot be empty.';
    passChangeMsg.className = 'form-msg err';
    return;
  }
  const dupe = users.find(u => u.id !== me.id && u.username.toLowerCase() === newUsername.toLowerCase());
  if (dupe){
    passChangeMsg.textContent = 'That username is already taken.';
    passChangeMsg.className = 'form-msg err';
    return;
  }

  const usernameChanged = newUsername.toLowerCase() !== me.username.toLowerCase();
  me.username = newUsername;

  let passwordChanged = false;
  if (isAdmin()){
    const newPass = document.getElementById('myNewPass').value;
    if (newPass){
      me.password = newPass;
      passwordChanged = true;
    }
  }

  saveJSON(STORAGE_KEYS.USERS, users);

  passChangeMsg.textContent = usernameChanged && passwordChanged
    ? 'Username and password updated successfully.'
    : usernameChanged
      ? 'Username updated successfully.'
      : passwordChanged
        ? 'Password updated successfully.'
        : 'No changes made.';
  passChangeMsg.className = 'form-msg ok';
  if (usernameChanged){
    logHistory(`${me.name} updated their username`, 'neutral');
  }
  if (passwordChanged){
    logHistory(`${me.name} changed their own password`, 'neutral');
  }
  document.getElementById('myNewPass').value = '';
  applyRoleUI();
  renderUsers();
});

/* ---------------------------------------------------------------
   PASSWORD REQUESTS
   Regular users can no longer change their own password — only an
   Owner/Admin can, via Users → Edit. Instead, anyone can send an
   in-app request; it shows up for the Owner/Admin on the Users page
   until they resolve it (after telling the person their new password
   directly, outside the app).
   --------------------------------------------------------------- */
document.getElementById('sendPasswordRequestBtn').addEventListener('click', () => {
  const me = getCurrentUser();
  if (!me) return;
  const noteInput = document.getElementById('passwordRequestNote');
  const note = noteInput.value.trim();
  const msgEl = document.getElementById('passwordRequestMsg');

  passwordRequests.unshift({
    id: uid(),
    userId: me.id,
    userName: me.name,
    note,
    time: new Date().toISOString(),
  });
  saveJSON(STORAGE_KEYS.PASSWORD_REQUESTS, passwordRequests);
  logHistory(`${me.name} requested a password change${note ? ' — "' + note + '"' : ''}`, 'neutral');

  noteInput.value = '';
  msgEl.textContent = 'Request sent — the Owner/Admin will set a new password and let you know.';
  msgEl.className = 'form-msg ok';
  renderPasswordRequests();
});

function renderPasswordRequests(){
  const panel = document.getElementById('passwordRequestsPanel');
  const list = document.getElementById('passwordRequestsList');
  if (!isAdmin() || passwordRequests.length === 0){
    panel.style.display = 'none';
    return;
  }
  panel.style.display = '';
  list.innerHTML = passwordRequests.map(r => `
    <div class="password-request-item">
      <div>
        <strong>${escapeHTML(r.userName)}</strong>
        ${r.note ? `<span class="password-request-note">— "${escapeHTML(r.note)}"</span>` : ''}
        <div class="password-request-time">${fmtDateTime(r.time)}</div>
      </div>
      <div class="row-actions">
        <button type="button" class="icon-btn" data-open-user="${r.userId}">Set New Password</button>
        <button type="button" class="icon-btn danger" data-resolve-req="${r.id}">Dismiss</button>
      </div>
    </div>
  `).join('');

  list.querySelectorAll('[data-open-user]').forEach(btn => {
    btn.addEventListener('click', () => {
      const u = users.find(x => x.id === btn.dataset.openUser);
      if (u) openUserModal(u);
    });
  });
  list.querySelectorAll('[data-resolve-req]').forEach(btn => {
    btn.addEventListener('click', () => {
      const req = passwordRequests.find(r => r.id === btn.dataset.resolveReq);
      passwordRequests = passwordRequests.filter(r => r.id !== btn.dataset.resolveReq);
      saveJSON(STORAGE_KEYS.PASSWORD_REQUESTS, passwordRequests);
      if (req){
        const me = getCurrentUser();
        logHistory(`Password request from ${req.userName} resolved by ${me ? me.name : 'Admin'}`, 'neutral');
      }
      renderPasswordRequests();
    });
  });
}

/* ---------------------------------------------------------------
   PHOTO REQUESTS
   Same idea as Password Requests: regular users can't set their own
   avatar anymore, so they upload the picture they want and send it
   for approval. The Owner/Admin sees a preview on the Users page and
   can Approve (applies it straight to the user's profile) or Reject.
   --------------------------------------------------------------- */
let pendingPhotoRequestImage = '';

document.getElementById('photoRequestInput').addEventListener('change', async (e) => {
  const file = e.target.files[0];
  e.target.value = '';
  if (!file) return;
  try{
    pendingPhotoRequestImage = await fileToResizedDataURL(file, 240);
    document.getElementById('photoRequestPreview').innerHTML = `<img src="${pendingPhotoRequestImage}" alt="">`;
  }catch(err){
    alert(err.message);
  }
});

document.getElementById('sendPhotoRequestBtn').addEventListener('click', () => {
  const me = getCurrentUser();
  if (!me) return;
  const msgEl = document.getElementById('photoRequestMsg');
  if (!pendingPhotoRequestImage){
    msgEl.textContent = 'Choose a photo first.';
    msgEl.className = 'form-msg err';
    return;
  }
  const noteInput = document.getElementById('photoRequestNote');
  const note = noteInput.value.trim();

  photoRequests.unshift({
    id: uid(),
    userId: me.id,
    userName: me.name,
    image: pendingPhotoRequestImage,
    note,
    time: new Date().toISOString(),
  });
  saveJSON(STORAGE_KEYS.PHOTO_REQUESTS, photoRequests);
  logHistory(`${me.name} requested a profile photo change${note ? ' — "' + note + '"' : ''}`, 'neutral');

  pendingPhotoRequestImage = '';
  document.getElementById('photoRequestPreview').innerHTML = '';
  noteInput.value = '';
  msgEl.textContent = 'Request sent — the Owner/Admin will review it and let you know.';
  msgEl.className = 'form-msg ok';
  renderPhotoRequests();
});

function renderPhotoRequests(){
  const panel = document.getElementById('photoRequestsPanel');
  const list = document.getElementById('photoRequestsList');
  if (!isAdmin() || photoRequests.length === 0){
    panel.style.display = 'none';
    return;
  }
  panel.style.display = '';
  list.innerHTML = photoRequests.map(r => `
    <div class="password-request-item">
      <div class="avatar-cell">
        <span class="avatar-circle"><img src="${r.image}" alt=""></span>
        <div>
          <strong>${escapeHTML(r.userName)}</strong>
          ${r.note ? `<span class="password-request-note">— "${escapeHTML(r.note)}"</span>` : ''}
          <div class="password-request-time">${fmtDateTime(r.time)}</div>
        </div>
      </div>
      <div class="row-actions">
        <button type="button" class="icon-btn" data-approve-photo="${r.id}">Approve & Apply</button>
        <button type="button" class="icon-btn danger" data-reject-photo="${r.id}">Reject</button>
      </div>
    </div>
  `).join('');

  list.querySelectorAll('[data-approve-photo]').forEach(btn => {
    btn.addEventListener('click', () => {
      const req = photoRequests.find(r => r.id === btn.dataset.approvePhoto);
      if (!req) return;
      const u = users.find(x => x.id === req.userId);
      if (u){
        u.avatar = req.image;
        saveJSON(STORAGE_KEYS.USERS, users);
      }
      photoRequests = photoRequests.filter(r => r.id !== req.id);
      saveJSON(STORAGE_KEYS.PHOTO_REQUESTS, photoRequests);
      const me = getCurrentUser();
      logHistory(`Photo request from ${req.userName} approved by ${me ? me.name : 'Admin'}`, 'income');
      applyRoleUI();
      renderUsers();
    });
  });
  list.querySelectorAll('[data-reject-photo]').forEach(btn => {
    btn.addEventListener('click', () => {
      const req = photoRequests.find(r => r.id === btn.dataset.rejectPhoto);
      photoRequests = photoRequests.filter(r => r.id !== btn.dataset.rejectPhoto);
      saveJSON(STORAGE_KEYS.PHOTO_REQUESTS, photoRequests);
      if (req){
        const me = getCurrentUser();
        logHistory(`Photo request from ${req.userName} rejected by ${me ? me.name : 'Admin'}`, 'expense');
      }
      renderPhotoRequests();
    });
  });
}

document.getElementById('exportBtn').addEventListener('click', () => {
  const backup = { orders, expenses, history, exportedAt: new Date().toISOString() };
  const blob = new Blob([JSON.stringify(backup, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `elite-digital-hub-backup-${new Date().toISOString().slice(0,10)}.json`;
  a.click();
  URL.revokeObjectURL(url);
  logHistory('Data backup exported', 'neutral');
});

document.getElementById('importInput').addEventListener('change', (e) => {
  if (!isAdmin()){
    e.target.value = '';
    return;
  }
  const file = e.target.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = () => {
    try{
      const data = JSON.parse(reader.result);
      confirmAction(
        'Import this backup?',
        'This will replace all current orders, expenses and history in this browser.',
        () => {
          orders = data.orders || [];
          expenses = data.expenses || [];
          history = data.history || [];
          saveJSON(STORAGE_KEYS.ORDERS, orders);
          saveJSON(STORAGE_KEYS.EXPENSES, expenses);
          saveJSON(STORAGE_KEYS.HISTORY, history);
          logHistory('Data backup imported', 'neutral');
          renderAll();
        }
      );
    }catch(err){
      alert('Invalid backup file.');
    }
    e.target.value = '';
  };
  reader.readAsText(file);
});

document.getElementById('resetBtn').addEventListener('click', () => {
  if (!isAdmin()) return;
  confirmAction(
    'Erase all data?',
    'This permanently deletes every order, expense and history entry in this browser. This cannot be undone.',
    () => {
      orders = [];
      expenses = [];
      history = [];
      saveJSON(STORAGE_KEYS.ORDERS, orders);
      saveJSON(STORAGE_KEYS.EXPENSES, expenses);
      saveJSON(STORAGE_KEYS.HISTORY, history);
      renderAll();
    }
  );
});

/* ---------------------------------------------------------------
   MODAL / CONFIRM HELPERS
   --------------------------------------------------------------- */
function closeModal(modalEl){
  modalEl.classList.add('hidden');
}
[itemModal, orderModal, expenseModal, invoiceModal, userModal, taskModal].forEach(modal => {
  modal.addEventListener('click', (e) => {
    if (e.target === modal) closeModal(modal);
  });
});

const confirmModal = document.getElementById('confirmModal');
const confirmTitle = document.getElementById('confirmTitle');
const confirmMsg = document.getElementById('confirmMsg');
const confirmOkBtn = document.getElementById('confirmOkBtn');
const confirmCancelBtn = document.getElementById('confirmCancelBtn');
let pendingConfirmAction = null;

function confirmAction(title, msg, onConfirm){
  confirmTitle.textContent = title;
  confirmMsg.textContent = msg;
  pendingConfirmAction = onConfirm;
  confirmModal.classList.remove('hidden');
}
confirmOkBtn.addEventListener('click', () => {
  if (pendingConfirmAction) pendingConfirmAction();
  pendingConfirmAction = null;
  confirmModal.classList.add('hidden');
});
confirmCancelBtn.addEventListener('click', () => {
  pendingConfirmAction = null;
  confirmModal.classList.add('hidden');
});
confirmModal.addEventListener('click', (e) => {
  if (e.target === confirmModal){
    pendingConfirmAction = null;
    confirmModal.classList.add('hidden');
  }
});

/* ---------------------------------------------------------------
   UTIL
   --------------------------------------------------------------- */
function escapeHTML(str){
  const div = document.createElement('div');
  div.textContent = str;
  return div.innerHTML;
}

/* Auto-formats a phone input as 4 digits, dash, remaining digits (e.g. 0300-1234567) */
function attachPhoneFormatter(input){
  if (!input) return;
  input.addEventListener('input', () => {
    const start = input.selectionStart;
    const rawBeforeCursor = input.value.slice(0, start).replace(/\D/g, '').length;
    const digits = input.value.replace(/\D/g, '').slice(0, 11);
    const formatted = digits.length > 4 ? digits.slice(0, 4) + '-' + digits.slice(4) : digits;
    input.value = formatted;
    let pos = rawBeforeCursor > 4 ? rawBeforeCursor + 1 : rawBeforeCursor;
    pos = Math.min(pos, formatted.length);
    input.setSelectionRange(pos, pos);
  });
}
attachPhoneFormatter(document.getElementById('orderContact'));
attachPhoneFormatter(document.getElementById('invoiceContact'));

